"約 5,000 – 9,000 K": "about 5,000 – 9,000 K",
"気化したアルミニウムが衝撃層の高温酸素と反応して生成される。終端まで残ることがあり、アルミ片が最後まで溶け残っていたことを示す": "Formed when vaporised aluminium reacts with hot oxygen in the shock layer. It can persist to the end of the trail, showing that aluminium fragments survived unmelted to the last moment.",
