"衝突破片": "Collision fragment",
"公開軌道要素（TLE）＋大気密度モデル": "Public orbital elements (TLE) plus an atmospheric density model",
"検出": "Detection",
"7 局で同時検出。エッジ AI が火球候補として自動判定（信頼度 0.98）": "Detected simultaneously at seven stations; the edge AI flagged it automatically as a fireball candidate (confidence 0.98)",
"解析": "Analysis",
"多点三角測量による軌跡決定が完了（残差 41 m）。絶対等級 −11.8、突入速度 17.4 km/s": "Multi-station triangulation completed the trajectory (residual 41 m): absolute magnitude −11.8, entry speed 17.4 km/s",
"暗黒飛行（ダークフライト）の風補正（気象庁 数値予報 GPV ＋ 高層気象観測 ＋ 自局の気象センサー）による落下域確率地図を生成": "A fall-zone probability map was produced with dark-flight wind correction (JMA numerical forecast GPV, upper-air soundings and the stations’ own weather sensors)",
"通報": "Alert",
"千葉県山武市・東金市の防災課、千葉県教育委員会へ落下域確率地図を自動配信（検出から 3 分 42 秒）": "The fall-zone probability map was sent automatically to the disaster management divisions of Sanmu and Togane and to the Chiba Prefectural Board of Education (3 min 42 s after detection)",
"確認": "Confirmation",
"船橋局でインフラサウンド到達を確認。音響エネルギー推定値が光学推定と 2 倍以内で整合": "Infrasound arrival confirmed at Funabashi; the acoustic energy estimate agrees with the optical one to within a factor of two",
"対応": "Response",
"山武市より「被害報告なし」の回答。翌朝から回収捜索を開始（UAV 2 機・地上班 6 名）": "Sanmu City replied that no damage had been reported. The recovery search began the next morning with two UAVs and a six-person ground team.",
"予報": "Forecast",
"公開軌道要素から再突入予報を発出（予報窓 ±32 分、日本上空通過の可能性 62 %）": "A re-entry forecast was issued from public orbital elements (window ±32 min, 62 % chance of passing over Japan)",
"6 局で再突入発光を検出。経路角 1.4°・継続 38 秒から人工物と即時判定": "Six stations detected the re-entry emission; a path angle of 1.4° and a duration of 38 s identified it immediately as artificial",
"共有": "Sharing",
"JAXA 宇宙状況把握（SSA）へ観測結果を共有。予報誤差 11.4 分 / 640 km を報告": "Results shared with JAXA Space Situational Awareness (SSA), reporting a forecast error of 11.4 min / 640 km",
"注意喚起": "Advisory",
"線状降水帯に伴う雷放電群を検知。関東 5 校へ屋外活動の中止を推奨（検知から 4 分）": "A lightning cluster in a training rainband was detected; five schools in Kanto were advised to cancel outdoor activity (4 min after detection)",
"判定": "Assessment",
"地震後の校舎固有振動数チェックを 3 局で自動実施。いずれも「継続使用可」": "Post-earthquake natural-frequency checks ran automatically at three stations; all came back “fit for continued use”",
"検知": "Detection",
"房総半島東部で雷放電音を連続検知（3 局・10 分あたり 24 回）。線状降水帯の形成を監視状態へ": "Lightning sounds detected continuously over the eastern Boso Peninsula (three stations, 24 per 10 min); monitoring for the formation of a training rainband",
"インフラサウンドの方位交会・GNSS 可降水量・気圧の 6 条件が成立し、線状降水帯の可能性を自動判定": "Six criteria on infrasound bearing intersection, GNSS precipitable water and pressure were met, and a training rainband was flagged automatically",
"千葉県 山武市・東金市・茂原市 と県東部の付属校 3 校へ発報（判定から 4 分、外部の大雨情報に 34 分先行）": "Alerts went to Sanmu, Togane and Mobara and to three affiliated schools in eastern Chiba (4 min after the assessment, 34 min ahead of the external heavy-rain bulletin)",
"雷放電の検知が 10 分あたり 5 回を下回り、帯の解消を判定。学校へ解除連絡": "Lightning detections fell below 5 per 10 min, the band was judged to have dissipated, and the all-clear went to the schools",
"形成": "Formation",
"房総半島東部（茂原市付近）で対流セルが次々と発生し、南北に並び始める": "Convective cells form one after another over the eastern Boso Peninsula near Mobara and begin to line up north–south",
"インフラサウンド": "Infrasound",
"船橋・駿河台・桜上水の 3 局が 0.6–14 Hz の雷放電音を連続検知（10 分あたり 24 回）": "Funabashi, Surugadai and Sakurajosui detect lightning sounds at 0.6–14 Hz continuously (24 per 10 min)",
"定位": "Location",
"5 局の到来方位を交会し、音源が長さ 78 km・幅 22 km の帯状に並ぶことを確認（定位精度 ±9 km）": "Intersecting the bearings from five stations confirms that the sources lie along a band 78 km long and 22 km wide (location accuracy ±9 km)",
"前兆": "Precursor",
"2 周波 GNSS": "Dual-frequency GNSS",
"船橋局の可降水量（PWV）が 43 → 58 mm（＋35 %）。下層への強い水蒸気流入を示す": "Precipitable water vapour at Funabashi rises from 43 to 58 mm (+35 %), showing a strong low-level moisture inflow",
"統合判定": "Combined assessment",
"「雷放電 ≥ 30 回/10 分」「到来方位の集中 ≤ ±10°」「音源の線状配列」「PWV ≥ 55 mm」の 4 条件が成立し、線状降水帯の可能性を自動判定": "All four criteria — ≥ 30 lightning events per 10 min, bearing spread ≤ ±10°, sources in a linear arrangement, and PWV ≥ 55 mm — are met, and a training rainband is flagged automatically",
"千葉県 山武市・東金市・茂原市 の防災担当と、県東部の付属校 3 校へ発報（判定から 4 分）": "Alerts go to the disaster managers of Sanmu, Togane and Mobara and to three affiliated schools in eastern Chiba (4 min after the assessment)",
