"参照した実事象：2023 年 9 月 8 日、台風第 13 号に伴い千葉県で線状降水帯が発生し、気象庁が「顕著な大雨に関する情報」を発表した事例（茂原市などで記録的な大雨）。本デモの数値は当該事象を模した模擬データであり、実際の観測記録ではない。": "Reference event: on 8 September 2023 a training rainband associated with Typhoon No. 13 formed over Chiba Prefecture and JMA issued its “significant heavy rainfall” bulletin, with record rain around Mobara. The figures in this demo are simulated to resemble that event and are not real observations.",
