"本観測網は気象庁の津波警報を置き換えるものではない。警報の後に届く「実際にどれだけの津波が来るか」を、電離圏と大気の応答から独立に見積もり、沿岸から離れた学校の判断材料として補うことを目的とする。": "This network is not a replacement for JMA tsunami warnings. Its purpose is to add, after the warning, an independent estimate of how large the tsunami will actually be — derived from the ionospheric and atmospheric response — as extra input for schools away from the coast.",
