"全国約 1,700 点の強震計。地表と地中の加速度波形": "About 1,700 strong-motion sensors nationwide, recording acceleration at the surface and in boreholes",
"本観測網の微動計（14 局・校舎屋上）の記録を、近傍の K-NET 観測点と突き合わせて、地盤の揺れと校舎の応答を分離する": "Records from this network’s microtremor sensors (14 rooftop stations) are compared with the nearest K-NET site to separate ground shaking from the building’s own response",
"災害": "Disaster",
"高感度地震観測網": "High-sensitivity seismograph network",
"全国約 800 点の高感度地震計。微小地震まで捉える連続波形": "About 800 high-sensitivity seismometers nationwide, recording continuously down to microearthquakes",
"火球の衝撃波は地面も揺らすため、大火球の到達時刻を Hi-net の連続波形から探し、インフラサウンドの到達時刻と突き合わせて音源高度を拘束する": "A fireball’s shock wave also shakes the ground, so the arrival time of a bright fireball is searched for in the Hi-net continuous waveforms and compared with the infrasound arrival to constrain the source altitude",
"広帯域地震観測網": "Broadband seismograph network",
"広帯域地震計 73 点。長周期の地面変動とモーメントテンソル解": "73 broadband seismometers, giving long-period ground motion and moment-tensor solutions",
"大気重力波・ラム波による地面の応答（空振と地動の結合）を長周期側で確認する。火山噴火・大規模爆発の規模推定に使う": "Used to check the long-period ground response to atmospheric gravity waves and Lamb waves — the coupling between air pressure and ground motion — and to estimate the size of eruptions and large explosions",
"S-net・DONET": "S-net / DONET",
"海底地震津波観測網": "Seafloor earthquake and tsunami observation networks",
"日本海溝・南海トラフの海底に敷設した地震計と水圧計": "Seismometers and pressure gauges on the seafloor along the Japan Trench and Nankai Trough",
"津波の実測（水圧計）を、本観測網の電離圏 TEC から推定した津波規模の検証に使う。海面変動 → 大気 → 電離圏という結合の出発点を押さえる": "Direct tsunami measurements from the pressure gauges are used to verify the tsunami size this network infers from ionospheric TEC, pinning down the starting point of the sea-surface → atmosphere → ionosphere chain",
"津波": "Tsunami",
"地震被害推定即時公開システム": "Real-time earthquake damage estimation system",
"地震発生後に約 250 m メッシュで震度分布と被害を即時推定": "Estimates the seismic intensity distribution and damage on a ~250 m grid immediately after an earthquake",
"校舎の使用可否判定（微動計・DT-6）を、周辺の推定震度と並べて自治体へ示す。学校が避難所として使えるかの判断材料になる": "The building usability assessment (microtremor sensors, DT-6) is presented to local authorities alongside the estimated intensity nearby, as input for deciding whether a school can serve as an evacuation centre",
"地震ハザードステーション": "Japan Seismic Hazard Information Station",
"全国地震動予測地図、表層地盤増幅率、活断層": "National seismic hazard maps, near-surface amplification factors, active faults",
"各観測局の地盤条件（増幅率）を取り込み、微動計の記録から校舎固有振動数を同定する際の基準にする": "The ground conditions (amplification factor) at each station are taken in as the reference for identifying building natural frequencies from the microtremor records",
"基盤的火山観測網": "Fundamental volcano observation network",
"全国 16 火山の地震計・傾斜計・空振計・GNSS": "Seismometers, tiltmeters, infrasound sensors and GNSS at 16 volcanoes nationwide",
"本観測網のインフラサウンドによる火山の定位結果を、V-net の火口近傍の空振計と突き合わせて、遠方からの規模推定を較正する": "Volcano locations derived from this network’s infrasound are compared with V-net sensors near the crater to calibrate long-range size estimates",
