"災害発生時に各機関の情報を集約して地図で公開（SIP4D）": "Aggregates information from many agencies during a disaster and publishes it on a map (SIP4D)",
"落下域確率地図・線状降水帯の判定・校舎判定を、この枠組みへ流し込む形式で出力する。自治体が既に見ている画面に載せることが社会実装の近道になる": "Fall-zone probability maps, rainband assessments and building assessments are output in a form that feeds into this framework. Putting them on a screen local authorities already watch is the shortest route to real-world use.",
