"リモート運用 × デジタルツイン試験": "Remote operation × digital-twin testbed",
"船橋局には、観測網の標準機材に加えて、口径 400 mm と 200 mm のカセグレン式望遠鏡を 1 台のフォーク式赤道儀に同架した「ガンダム望遠鏡」がある。月面衝突閃光の観測のために構築されたシステムで、屋上観測網が捉える地球大気への突入現象に対して、同じ流星物質が「大気のない月面に衝突したとき」を同時に押さえられる。スペースデブリの追跡と一般の天体観測にも使い、遠隔操作と観測計画の自動化を通じてデジタルツインの試験台とする。": "Besides the network’s standard instruments, Funabashi has the “Gundam Telescope”: 400 mm and 200 mm Cassegrain tubes co-mounted on a single fork equatorial mount. Built to observe lunar impact flashes, it can catch the same meteoritic material striking the airless lunar surface at the same time as the rooftop network catches entries into Earth’s atmosphere. It is also used for tracking space debris and for general astronomy, and its remote operation and automated scheduling make it a testbed for the digital twin.",
