"実観測データ": "Real observations",
"月には大気がないため、流星物質はそのまま地面に衝突して閃光を出す。大気中で燃え尽きる地上の流星観測と組み合わせると、同じ母天体から出た粒子の、質量の大きい側の分布を直接押さえられる。船橋局の屋上観測網がふたご座流星群を大気側で数えている同じ夜に、ガンダム望遠鏡が月面側を数える、という使い方をする。": "The Moon has no atmosphere, so meteoritic material strikes the surface directly and produces a flash. Combined with ground-based meteor observations, where the particle burns up in the air, this gives direct access to the high-mass end of the distribution from the same parent body. On the same night that Funabashi’s rooftop network counts Geminids on the atmospheric side, the Gundam Telescope counts them on the lunar side.",
