"丸の大きさは最大 R 等級（明るいほど大きい）。11 個すべてが夜側（地球照側）に集中しているのは、この時期にふたご座流星群の放射点方向が月の夜側を向いていたため。": "Circle size follows peak R magnitude — brighter flashes are larger. All eleven fall on the night side lit by earthshine because at that time the Geminid radiant faced the Moon’s night hemisphere.",
"最大 R 等級の累積分布": "Cumulative distribution of peak R magnitude",
"冪指数 <b>r = 2.35 ± 0.42</b>。NELIOTA（口径 1.2 m, r = 3.42 ± 0.22）や NASA（0.35 / 0.5 m, 群流星 r = 3.65 ± 0.40）と比べて明るい閃光の割合が高く、活動小惑星 (3200) Phaethon を母天体にもつ流星群の特徴と考えられる。": "The population index is <b>r = 2.35 ± 0.42</b>. Compared with NELIOTA (1.2 m telescope, r = 3.42 ± 0.22) and NASA (0.35 / 0.5 m, r = 3.65 ± 0.40 for shower meteors), a larger fraction of the flashes are bright — plausibly a signature of a shower whose parent is the active asteroid (3200) Phaethon.",
