"昼間・曇天でも計数できる出現数": "Counts that work in daylight and under cloud",
"月面衝突閃光の継続監視は、将来の月面活動における衝突リスクの評価につながるほか、月震計と組み合わせれば月の内部構造の推定にも使える。本研究では衝突地点を": "Continuous monitoring of lunar impact flashes feeds into assessing the impact risk to future activity on the Moon, and combined with seismometers it can constrain the Moon’s interior structure. Here the impact points were fixed to ",
"の精度で決められたため、NASA の月周回衛星 LRO の狭視野カメラ（空間分解能 0.5 m）による衝突クレータの同定が期待される。クレータ径が判明すれば、未解明の発光効率 η を決められる。": ", good enough that the craters may be identifiable in NASA Lunar Reconnaissance Orbiter narrow-angle camera images at 0.5 m resolution. Once a crater diameter is known, the still-unsettled luminous efficiency η can be pinned down.",
