"副鏡 200 mm（視野 1.08° × 0.68°）で捕捉し、主鏡 400 mm で追跡する": "Acquired with the 200 mm secondary (1.08° × 0.68° field) and tracked with the 400 mm primary",
"デモ用の模擬データ": "Simulated demo data",
"公開軌道要素（TLE）から予報した通過に合わせて自動で追尾し、測光する。光度の周期変化から物体の自転周期と姿勢の乱れが分かり、再突入の時期と破砕のしかたの予測に効く。デブリ再突入の画面で扱う「落ちてくる瞬間の分光」に対して、こちらは「落ちる前の状態」を押さえる役割を持つ。": "The telescope tracks and measures passes predicted from public orbital elements (TLE). Periodic brightness variation reveals the object’s rotation period and any tumbling, which sharpens predictions of when it will re-enter and how it will break up. Where the debris re-entry page covers the spectrum at the moment of fall, this covers the state of the object before it falls.",
