"自転周期 (s)": "Rotation period (s)",
"角速度は視野を横切る速さ。LEO の物体は 1 秒あたり数百〜数千秒角で動くため、赤道儀の追尾速度を軌道要素から与えて恒星時追尾を打ち消す。": "The angular rate is how fast the object crosses the field. LEO objects move hundreds to thousands of arcseconds per second, so the mount is driven from the orbital elements to cancel sidereal tracking.",
"光度曲線から求める自転周期（": "Rotation period from the light curve (",
"極大と極小の間隔から自転周期 <b>": "The spacing of maxima and minima gives a rotation period of <b>",
" 秒</b>。周期の時間変化を追うと、姿勢制御を失った物体の減速（大気抵抗トルク）が見え、再突入予報の精度が上がる。": " s</b>. Following how that period changes over time reveals the aerodynamic torque slowing an uncontrolled object, which improves the re-entry forecast.",
"デブリ再突入の画面へ →": "Go to debris re-entry →",
