"(3200) Phaethon の測光": "Photometry of (3200) Phaethon",
"ふたご座流星群の母天体。近日点通過前後の明るさと色の変化を追い、ダスト放出の有無を調べる": "The parent of the Geminids. Following its brightness and colour around perihelion tests whether dust is being released.",
"小惑星による恒星掩蔽": "Stellar occultations by asteroids",
"恒星が隠される時刻を多地点で測り、小天体の形と大きさを求める。付属校と合同で観測地点を分散させる": "Timing the disappearance of a star from several sites gives the shape and size of the small body. Affiliated schools help spread the observing sites out.",
"彗星の活動監視": "Monitoring comet activity",
"コマの広がりと明るさの変化から、ダスト放出率を見積もる": "Estimating the dust production rate from the size of the coma and how its brightness changes",
