"長時間の連続測光。観測装置の安定性（測光精度）の日常的な確認にもなる": "Long continuous photometry, which doubles as a routine check on the instrument’s photometric stability",
"流星群の輻射点方向の監視": "Monitoring toward meteor shower radiants",
"全天カメラが検出した火球の対応天体を、拡大視野で追確認する": "Following up, at higher magnification, the objects behind fireballs the all-sky cameras have caught",
"③ 天体観測": "3. Astronomical observation",
"分解能 0.8″ を活かした測光と位置測定": "Photometry and astrometry that exploit the 0.8″ resolution",
"月面衝突閃光とデブリの観測がない夜は、一般の天体観測にあてる。屋上観測網が「広く浅く」24 時間休まず見るのに対して、ガンダム望遠鏡は「狭く深く」見る。両者を組み合わせることで、観測網が拾った事象をその場で拡大追跡できる。": "On nights with no lunar impact flash or debris work, the telescope goes to general astronomy. Where the rooftop network watches wide and shallow around the clock, the Gundam Telescope looks narrow and deep. Together they allow an event the network picks up to be followed up immediately at higher magnification.",
