"ドームの開閉・鏡筒の指向・カメラの露出を遠隔から操作する。観測条件のインターロックは船橋局の複合気象センサーと全天カメラの実測で判定し、どれか一つでも外れると自動で閉じる。観測予約は学部横断のキューで管理し、月面衝突閃光の好条件（月齢と夜側の向き）が最優先で割り込む。": "Dome opening, pointing and camera exposure are all controlled remotely. The observing interlock is judged from Funabashi’s weather sensor and all-sky camera, and the dome closes automatically if any single condition fails. Observing time is managed in a queue shared across the colleges, and favourable lunar impact flash conditions — the right lunar age and night-side geometry — take top priority.",
"観測条件インターロック（船橋局の実測で判定）": "Observing interlock (judged from Funabashi measurements)",
