"−10 ℃ 到達 · 安定": "At −10 °C, stable",
"インターロックはデモとして船橋局の気象センサー・全天カメラ・太陽高度から判定している。実運用では雨感知器と風速計のハードウェア信号を直接ドーム制御に入れ、通信が切れた場合も自動で閉じる設計とする。": "For this demo the interlock is judged from Funabashi’s weather sensor, all-sky camera and the solar altitude. In real operation the rain detector and anemometer would feed the dome controller in hardware, so the dome still closes automatically if the link drops.",
"観測予約キュー（今夜）": "Observing queue for tonight",
