" 分": " min",
"月面衝突閃光は月齢 3 – 10 と 20 – 27 の限られた期間しか観測できないため、<b>最優先</b>で割り込む。空いた時間をデブリ追跡と天体観測に自動で埋める計画作成を、そのままデジタルツインの試験対象にしている。": "Lunar impact flashes can only be observed at lunar ages 3–10 and 20–27, so they take <b>top priority</b>. Automatically filling the remaining time with debris tracking and astronomy is itself one of the things the digital twin is being tested on.",
