"ピリオディックエラーを学習して先回り補正する": "Periodic error is learned and corrected in advance",
"鏡筒たわみ": "Tube flexure",
"子午線越え前後の指向差": "Pointing difference across a meridian flip",
"1.2′ 以内": "Within 1.2′",
"重力方向と鏡筒姿勢から残差を予測するモデル": "A model that predicts the residual from the gravity vector and tube attitude",
"外気温変化による焦点移動": "Focus shift with outside air temperature",
"±25 µm 以内": "Within ±25 µm",
"気象センサーの気温からモデルで先に焦点を動かす": "The model moves the focuser ahead of time using the weather sensor’s temperature",
"シーイング": "Seeing",
"大気ゆらぎによる星像の広がり": "Blurring of star images by atmospheric turbulence",
"全天カメラの星像から推定し、露出時間の自動決定に使う": "Estimated from star images in the all-sky camera and used to set exposure times automatically",
"指令遅延": "Command latency",
"遠隔操作の往復遅延": "Round-trip latency of remote control",
"400 ms 以内": "Within 400 ms",
"遅延を見込んだ先読み指令で、高速移動天体の追尾を保つ": "Commands are issued ahead of time to allow for the delay, keeping fast-moving objects in the field",
"⑤ デジタルツイン試験台としての利用": "5. Use as a digital-twin testbed",
"実機とモデルの差を常時測り、観測網全体のデジタルツイン（DT-1 – DT-7）の検証に使う": "The gap between hardware and model is measured continuously and used to validate the network-wide digital twin (DT-1 – DT-7)",
"観測網のデジタルツインは、屋上の各センサーを仮想空間に写して「観測される前に予測する」ことを目指す。ただし予測がどれだけ当たるかは、実機と突き合わせなければ分からない。ガンダム望遠鏡は、指向・追尾・焦点という物理量が数値で厳密に測れるため、モデルと実機の差を定量化する試験台として適している。ここで確立した「モデル ↔ 実機の差を測り、モデルを直す」手順を、そのまま全 14 局のセンサーツインに適用する。": "The network’s digital twin aims to mirror every rooftop sensor in a virtual space and predict what will be observed before it is observed. How well those predictions hold, though, can only be learned by checking them against real hardware. The Gundam Telescope suits that job because pointing, tracking and focus are physical quantities that can be measured precisely. The procedure established here — measure the gap between model and hardware, then correct the model — carries over directly to the sensor twins at all 14 stations.",
"指向残差": "Pointing residual",
"目標 1.5′ 以内": "Target: within 1.5′",
"追尾残差": "Tracking residual",
"目標 2″/min 以内": "Target: within 2″/min",
"指令往復遅延": "Command round-trip latency",
"遠隔操作の応答性": "Responsiveness of remote control",
"全天カメラの星像から推定": "Estimated from all-sky camera star images",
"測る量": "Quantity measured",
"現在の残差": "Current residual",
"モデル側の扱い": "How the model handles it",
"DT-1（落下域）・DT-4（音源定位）・DT-5（地震応答）の各ツインは、いずれも「センサーの実測とモデル予測の差」を縮める設計になっている。": "The DT-1 (fall zone), DT-4 (source location) and DT-5 (seismic response) twins are all designed to narrow the gap between measurement and model prediction. ",
"ガンダム望遠鏡では同じ枠組みを、誤差 1′ 以下という厳しい条件で試せる。遠隔操作の遅延を含めた制御まで検証できる点も、": "The Gundam Telescope lets the same framework be tested under the far tighter requirement of better than 1′, and it also allows control including remote-operation latency to be validated — which ",
"将来の無人観測局（付属校拠点の自動運用）にそのまま生きる。": "carries straight over to future unattended stations, i.e. automated operation of the affiliated-school sites.",
