"14 局の配置・視野・観測値を地図上で重ねて見る。視野円は高度 100 km の発光点を各仰角以上で見込める地表範囲を示し、円が重なる領域で多点同時観測（三角測量）が成立する。船橋局と津田沼局は 5.1 km しか離れていないが、これは短基線のインフラサウンドアレイとして方位推定の精度を上げ、全天カメラの相互較正にも使える。局のマーカーをクリックすると、その局の全データ一覧（全天カメラ・インフラサウンド・気象・夜空輝度・電波流星 FFT・GNSS・微動計）へ移動する。": "Station positions, fields of view and measurements overlaid on a map. Each field circle is the area of ground from which a light point at 100 km altitude appears above the given elevation angle; where circles overlap, simultaneous multi-station triangulation becomes possible. Funabashi and Tsudanuma are only 5.1 km apart, which makes them a short-baseline infrasound array with sharper bearing estimates and allows the two all-sky cameras to be cross-calibrated. Click a station marker to open its full data view: all-sky camera, infrasound, weather, sky brightness, radio meteor FFT, GNSS and microtremor.",
