"恒星はエール輝星星表（BSC5）9,096 個、天の川は Tycho-2 の星数密度。雲・流星・人工衛星の軌跡・空の明るさは模擬": "Stars from the Yale Bright Star Catalogue (BSC5, 9,096 stars); the Milky Way from Tycho-2 star densities. Clouds, meteors, satellite trails and sky brightness are simulated.",
