"インフラサウンド 実況グラフ（全 14 局）": "Live infrasound traces (all 14 stations)",
"複合型センサー（サヤ INF03 ／ 高知工科大学と共同開発の ADXII-INF01 系）の 6 チャンネル。0.5 秒ごとに更新": "Six channels from the combined sensor (SAYA INF03 / the ADXII-INF01 series developed with Kochi University of Technology), refreshed every 0.5 s",
"チャンネル": "Channels",
"HF（1–20 Hz）は雷放電・爆発音・近傍の人工雑音、MF（0.1–1 Hz）は海洋起源の脈動微気圧振動（マイクロバロム）と火球の衝撃波、LF（0.005–0.1 Hz）は大気重力波・津波・気圧変動を捉える帯域。X・Y・Z は 3 成分加速度で、常時微動から校舎の固有振動数を求め、地震後の使用可否判定（DT-6）に使う。": "HF (1–20 Hz) covers lightning, explosions and nearby anthropogenic noise; MF (0.1–1 Hz) covers ocean-generated microbaroms and fireball shock waves; LF (0.005–0.1 Hz) covers atmospheric gravity waves, tsunamis and pressure changes. X, Y and Z are three-component acceleration, from which ambient vibration gives the building’s natural frequency for post-earthquake usability screening (DT-6).",
"表示の体裁は、一般財団法人 日本気象協会「インフラサウンド・モニタリング・ネットワーク」の実況グラフ（micos-sc.jwa.or.jp/infrasound-net/observed/）および高知工科大学インフラサウンド観測ネットワーク KISONS（geosci.mydns.jp/infrasound/graph.php）を参考にした。表示している波形はデモ用の模擬データであり、実観測ではない。": "The layout follows the live traces of the Japan Weather Association’s Infrasound Monitoring Network (micos-sc.jwa.or.jp/infrasound-net/observed/) and the KISONS infrasound network of Kochi University of Technology (geosci.mydns.jp/infrasound/graph.php). The waveforms shown here are simulated for this demo, not real observations.",
"複合気象センサー（全 14 局）": "All-in-one weather sensors (all 14 stations)",
"Vaisala WXT530 系。気温・湿度・気圧・風向風速・雨量・日射を 1 分値で取得し、WBGT を算出する": "Vaisala WXT530 series. Temperature, humidity, pressure, wind, rainfall and solar radiation are recorded once a minute, and WBGT is derived from them.",
"地上 1.5 km 以下の風は暗黒飛行（ダークフライト）の風補正にそのまま使われる（G-1）。WBGT は屋上 1 点の値で、校庭内の分布は校舎 3D モデルでダウンスケーリングする（G-6 / DT-3）。": "Winds below 1.5 km feed directly into the dark-flight wind correction (G-1). WBGT is a single rooftop value; its distribution across the schoolyard is downscaled with a 3D model of the buildings (G-6 / DT-3).",
"夜空輝度計（全 14 局）": "Sky quality meters (all 14 stations)",
"Unihedron SQM-LU-DL ＋ 窓付き野外ハウジング。視野 FWHM 約 20°、天頂向き、IR カット": "Unihedron SQM-LU-DL in a weatherproof housing with a window: ~20° FWHM field, pointed at the zenith, IR-cut",
"昼間・薄明の局は平常値を表示している。全天カメラの恒星測光と相互較正し、人工光・月・雲・衛星コンステレーションの寄与を分離する（G-3 / DT-2）。": "Stations in daylight or twilight show their normal value. Cross-calibrating against stellar photometry from the all-sky camera separates the contributions of artificial light, the Moon, cloud and satellite constellations (G-3 / DT-2).",
"電波流星受信機（全 14 局・FFT 画面）": "Radio meteor receivers (all 14 stations, FFT display)",
"HRO 方式：53.755 MHz の連続波ビーコンの前方散乱を受信。表示は HROFFT 形式のスペクトログラム（横軸 時刻／縦軸 ビーコンからの周波数差／色 強度）": "HRO method: forward scatter of the 53.755 MHz continuous-wave beacon. The display is an HROFFT-style spectrogram — time across, frequency offset from the beacon vertically, intensity in colour.",
" 弱 ← 受信強度 → 強": " weak ← signal strength → strong",
"0 Hz の横線＝ビーコンの直接波": "The horizontal line at 0 Hz is the direct beacon signal",
"短い輝点＝過疎エコー（暗い流星）": "Short bright dots are underdense echoes (faint meteors)",
"太い横帯＝過密エコー（明るい流星）": "Thick horizontal bands are overdense echoes (bright meteors)",
"立ち上がりの周波数降下＝ヘッドエコー": "A falling frequency at onset is a head echo",
"流星が残すプラズマ柱に電波が前方散乱され、見通し外の局にビーコンが届く。光学が使えない昼間・曇天・満月期でも流星数を数え続けられるため、全天カメラの検出効率の較正と、流星群の活動プロファイルの連続監視に使う。エコー継続時間は流星の明るさとおおむね対応する。": "Radio waves forward-scatter off the plasma column a meteor leaves behind, carrying the beacon beyond line of sight. Because meteors can still be counted in daylight, under cloud and around full moon — when optics cannot work — this is used to calibrate the all-sky cameras’ detection efficiency and to monitor shower activity profiles continuously. Echo duration corresponds roughly to meteor brightness.",
"2 周波 GNSS 受信機（全 14 局）": "Dual-frequency GNSS receivers (all 14 stations)",
"測地級 2 周波受信機（L1/L2、PPS 出力）。全局の時刻同期と電離圏 TEC を担う": "Geodetic-grade dual-frequency receivers (L1/L2, PPS output) providing network-wide time sync and ionospheric TEC",
"PPS 出力は全局共通の時刻基準で、多点三角測量とインフラサウンドの到達時刻差はこの精度に支えられている（同期 < 1 ms）。L1/L2 の搬送波位相差から求める TEC は、電離圏擾乱の検出（G-5 / DT-5）と GNSS 気象学による可降水量の算出に使う。": "The PPS output is the common time reference for the whole network; multi-station triangulation and infrasound arrival-time differences both rest on its accuracy (sync < 1 ms). TEC, derived from the L1/L2 carrier-phase difference, is used to detect ionospheric disturbances (G-5 / DT-5) and, through GNSS meteorology, to compute precipitable water vapour.",
"← 観測局一覧": "← Station list",
