"恒星はエール輝星星表（BSC5）の 9,096 個、星座線は IAU 公式星座図形、天の川は Tycho-2 の星数密度を用い、地方恒星時から地平座標へ変換して描いている（等距離魚眼投影・北が上・東が左）。色は B−V 色指数による。": "9,096 stars from the Yale Bright Star Catalogue (BSC5), the official IAU constellation figures, and Milky Way star densities from Tycho-2, converted from local sidereal time to horizontal coordinates (equidistant fisheye projection, north up, east left). Colours follow the B−V index. ",
