"サヤ INF03 ×2（基線約 60 m）。0.5 秒ごとに更新": "Two SAYA INF03 sensors (~60 m baseline), refreshed every 0.5 s",
"HF は雷放電・爆発音・近傍の人工雑音、MF は海洋起源の脈動微気圧振動（マイクロバロム）と火球の衝撃波、LF は大気重力波・津波・気圧変動。X・Y・Z は 3 成分加速度で常時微動を記録する。窓が長く搬送波を解像できない帯域は ±包絡線の帯として描いている。": "HF covers lightning, explosions and nearby anthropogenic noise; MF covers ocean-generated microbaroms and fireball shock waves; LF covers atmospheric gravity waves, tsunamis and pressure changes. X, Y and Z record ambient vibration as three-component acceleration. Where the window is too long to resolve the carrier, the trace is drawn as a ± envelope band.",
