"付属校拠点では、生徒が自動検出の誤検出（雲・虫・飛行機・人工衛星）を目視で検証する作業を探究学習として組み込む（G-8 / DT-7）。": "At the affiliated-school sites, students visually check false detections — cloud, insects, aircraft, satellites — as part of their inquiry-based learning (G-8 / DT-7).",
