"火球・隕石　多点観測と落下域確率地図": "Fireballs and Meteorites — multi-station observation and fall-zone probability maps",
"多点三角測量で軌跡と突入前軌道を決め、光学とインフラサウンドで独立にエネルギーを推定する。暗黒飛行（ダークフライト）を風補正して落下域の確率地図を自治体へ配信する（上空の風は気象庁の数値予報 GPV と高層気象観測、地上付近は各局の気象センサー）（サブテーマ G-1 / DT-1）。": "Multi-station triangulation fixes the trajectory and the pre-entry orbit, and the energy is estimated independently from optics and from infrasound. Dark flight is corrected for wind and a fall-zone probability map is distributed to local authorities — using JMA numerical forecast GPV and upper-air soundings aloft, and each station’s own weather sensor near the ground (sub-themes G-1 / DT-1).",
