"活動中の流星群（IMO Meteor Shower Calendar）": "Active meteor showers (IMO Meteor Shower Calendar)",
"活動期間・極大日・極大時の太陽黄経 λ☉・ZHR は IMO の Working List による。推定 ZHR と輻射点高度は今夜 1 時・船橋局での値": "Activity period, peak date, solar longitude λ☉ at maximum and ZHR are from the IMO Working List. The estimated ZHR and radiant altitude are for 01:00 tonight at Funabashi.",
