"今夜は主要な流星群の活動期間にあたらない。検出されるのは散在流星が主体となる。": "No major shower is active tonight; detections will be mostly sporadic meteors.",
"検出カタログの母集団は、IMO の活動期間と ZHR に輻射点高度の効果（出現数 ∝ ZHR·sin h の 0.7 乗）を掛けた重みで決めている。散在流星は ZHR 10 相当として常に含める。速度は各群の大気圏突入速度に合わせてある。": "The catalogue population is weighted by the IMO activity period and ZHR together with the effect of radiant altitude (rate ∝ ZHR·sin h to the power 0.7). Sporadic meteors are always included at an equivalent ZHR of 10. Speeds match each shower’s atmospheric entry velocity.",
"出典：International Meteor Organization, Meteor Shower Calendar / IMO Working List of Meteor Showers（https://www.imo.net/resources/calendar/）。本デモでは主要 16 群を収録した。": "Source: International Meteor Organization, Meteor Shower Calendar / IMO Working List of Meteor Showers (https://www.imo.net/resources/calendar/). This demo includes the 16 major showers.",
"防災科研（NIED）の公開データとの突き合わせ": "Cross-checking against NIED open data",
"大火球の衝撃波は地面も揺らす。地震観測網の連続波形と突き合わせて音源高度を拘束する": "A bright fireball’s shock wave also shakes the ground; matching it against continuous seismic waveforms constrains the source altitude",
