"光学は Brown et al. (2002) の Er–E 関係、音響は AFTAC の周期–収量関係を用いた。独立な二つの推定が一致することが、単独センサー観測にない本観測網の強みである。": "The optical estimate uses the Er–E relation of Brown et al. (2002); the acoustic one uses the AFTAC period–yield relation. Having two independent estimates agree is exactly what a single-sensor observation cannot offer.",
"光度質量の発光効率依存": "Dependence of photometric mass on luminous efficiency",
"発光効率 τ の不確かさが質量推定の最大の誤差要因。インフラサウンドによるエネルギー独立推定と減速からの動的質量を突き合わせて τ を制約する。": "Uncertainty in the luminous efficiency τ is the largest source of error in the mass estimate. Comparing the independent infrasound energy estimate with the dynamic mass from deceleration constrains τ.",
