"この事象はエッジ計算機の自動検出と多点対応づけのみが完了している。詳細な軌道決定・落下域推定は、絶対等級 −6 等より明るい事象、または隕石落下の可能性がある事象について実施する。左の一覧から「房総沖 大火球」を選ぶと、完全な解析例を表示する。": "For this event only automatic edge detection and multi-station matching have been completed. Full trajectory determination and fall-zone estimation are run for events brighter than absolute magnitude −6, or where a meteorite fall is possible. Select “Boso Offshore Bright Fireball” in the list on the left to see a complete worked analysis.",
