"分子バンド（AlO 450–560 nm・CN 386–422 nm・TiO 515–725 nm）は検出されない。": "No molecular bands are present — AlO 450–560 nm, CN 386–422 nm, TiO 515–725 nm are all absent. ",
"これらはスペースデブリ再突入に特徴的で、自然天体と人工天体を分ける有力な指標になる（デブリ再突入の画面で ON / OFF を切り替えて比較できる）。": "These are characteristic of space debris re-entry and are a strong discriminator between natural and artificial objects; the debris re-entry page lets you switch them on and off to compare.",
"線同定と相対強度は、実際に取得された流星スペクトル（S. Abe et al., 2000, しし座流星群の分光観測 ほか）の代表例に合わせて構成した。表示している波形そのものはデモ用の合成スペクトルであり、実観測データではない。回折格子は 600 本/mm（600 lpm）を想定。": "The line identifications and relative intensities follow representative real meteor spectra (S. Abe et al., 2000, Leonid spectroscopy, among others). The trace shown is a synthetic spectrum made for this demo, not a real observation. A 600 lines/mm (600 lpm) grating is assumed.",
