"分子バンド（AlO・CN・TiO・FeO）の同定、励起温度、および 発光開始 → アブレーション → 爆発 → 分裂 → 終端 の推移は、": "The identification of the molecular bands (AlO, CN, TiO, FeO), their excitation temperatures, and the progression from first light through ablation, explosion and break-up to the terminal point follow ",
"Watanabe, Abe, Arima & Hanayama「Spectroscopic Study of Rocket Debris during Atmospheric Re-entry」（ACM 2026）による ": "Watanabe, Abe, Arima & Hanayama, “Spectroscopic Study of Rocket Debris during Atmospheric Re-entry” (ACM 2026), based on ",
"LM-3B 第 2 段の再突入分光観測（2024-12-21、石垣島天文台、Sony α7S ＋ SAMYANG 24mm F1.4 ＋ Edmund Optics 600 grooves/mm 透過型回折格子）に基づく。": "their spectroscopic observation of a LM-3B second stage re-entry (21 December 2024, Ishigakijima Astronomical Observatory; Sony α7S with SAMYANG 24 mm F1.4 and an Edmund Optics 600 grooves/mm transmission grating). ",
"同観測では CN の励起温度 約 12,000 K、AlO の励起温度 約 5,000–9,000 K、平均表面温度 5,436 K（サンプルリターンカプセルの約 2 倍）が得られている。": "That work found an excitation temperature of about 12,000 K for CN, about 5,000–9,000 K for AlO, and a mean surface temperature of 5,436 K — roughly twice that of a sample-return capsule. ",
"表示している波形そのものはデモ用の合成スペクトルであり、実観測データではない。": "The trace shown here is a synthetic spectrum made for this demo, not a real observation.",
"スペースデブリ再突入　光学・分光・音響観測": "Space Debris Re-entry — optical, spectroscopic and acoustic observation",
"公開軌道要素から再突入を予報し、光学・SWIR・分光・インフラサウンドで実観測する。破片化の過程と大気への金属注入量を地上から直接推定する（サブテーマ G-2 / DT-1）。": "Re-entries are forecast from public orbital elements and then actually observed in the optical, SWIR, spectroscopic and infrasound bands. The break-up sequence and the amount of metal injected into the atmosphere are estimated directly from the ground (sub-themes G-2 / DT-1).",
"再突入 予報（今後 5 日）": "Re-entry forecast (next 5 days)",
