"再突入予報の誤差は主に大気密度モデルと姿勢（断面積）の不確かさに由来する。実観測による検証データを蓄積し、JAXA 宇宙状況把握（SSA）へ共有する。": "Re-entry forecast errors come mainly from uncertainty in the atmospheric density model and in the object’s attitude, and hence its cross-section. Validation data from real observations is accumulated and shared with JAXA Space Situational Awareness (SSA).",
