"円の大きさは破片数。市区町村の境界は国土数値情報 行政区域データ（国土交通省）による": "Circle size follows the number of fragments. Municipal boundaries come from the National Land Numerical Information administrative area data (MLIT). Municipality names are shown in Japanese, as in the source data.",
"38 秒にわたる長い発光。4 回の主フレアが破片化に対応": "A long 38-second emission; the four main flares correspond to break-up events",
"自然火球の継続時間は通常 1〜5 秒。38 秒という長い発光と浅い経路角は、円軌道からの人工天体の再突入に特有である。": "Natural fireballs usually last 1–5 seconds. A 38-second emission and such a shallow path angle are characteristic of an artificial object re-entering from a near-circular orbit.",
