"インフラサウンド全国アレイ": "Nationwide Infrasound Array",
"全 14 局に 2 台ずつ（基線約 60 m のペア配置）設置したインフラサウンドセンサーを GNSS で時刻同期し、全国を一つのアレイとして扱う。火山噴火・雷・ロケット・津波・火球衝撃波を検知・定位し、線状降水帯の早期検知や成層圏風の逆推定にも用いる（サブテーマ G-4 / DT-4）。": "Two infrasound sensors at each of the 14 stations, deployed as pairs on a ~60 m baseline and synchronised by GNSS, let the whole country be treated as a single array. It detects and locates eruptions, lightning, rockets, tsunamis and fireball shock waves, and is also used for early detection of training rainbands and for inferring stratospheric winds (sub-themes G-4 / DT-4).",
