"実線は各局の到来方位、破線は方位誤差と到達時刻の等時線。赤丸は推定音源位置。市区町村の境界は国土数値情報 行政区域データ（国土交通省）による": "Solid lines are the arrival bearings from each station; dashed lines show the bearing uncertainty and arrival-time isochrones. The red circle is the estimated source. Municipal boundaries come from the National Land Numerical Information administrative area data (MLIT). Municipality names are shown in Japanese, as in the source data.",
