"空振から求めた火口位置と噴煙高度を、降灰予測の初期値として使う": "The crater position and plume height derived from the air wave serve as initial conditions for the ashfall forecast",
"地域（観測局からの目安）": "Area (by distance from the stations)",
"想定降灰": "Expected ashfall",
"学校の対応": "School response",
"降灰の分布は上空の風に強く依存する。本観測網は気象庁の数値予報 GPV（MSM）の風を使って初期の降灰域を見積もり、気象庁の降灰予報が出るまでの間、各校が自分の位置で判断できる材料を出す。気象庁の噴火警報・降灰予報が優先する。": "Where ash falls depends strongly on the winds aloft. This network uses winds from JMA numerical forecast GPV (MSM) to estimate an initial ashfall area, giving each school something to act on at its own location until the official JMA ashfall forecast is issued. JMA eruption warnings and ashfall forecasts take precedence.",
"解釈と応用": "Interpretation and use",
