" 回（6 時間）。気象センサーの気圧・雨量と同期させることで、降水帯の到達を数分先取りして学校へ伝えられる。": " over six hours. Synchronised with pressure and rainfall from the weather sensors, this warns schools a few minutes before the rainband arrives.",
