"校舎 1 次固有振動数の変化": "Change in the building’s first natural frequency",
"常時微動計（DT-6）· 地震前後の比較": "Ambient vibration sensors (DT-6) — before and after the earthquake",
"固有振動数は剛性の平方根に比例するため、低下率は構造損傷の指標になる。5 % を超えた場合に「点検要」を自動発報する。": "Natural frequency scales with the square root of stiffness, so the size of the drop indicates structural damage. A drop of more than 5 % triggers an automatic “inspection required” notice.",
"局別判定": "Assessment by station",
"震央距離": "Epicentral distance",
"地震前 f₀": "f₀ before",
"地震後 f₀": "f₀ after",
"変化": "Change",
"意義": "Significance",
" 観測局を載せる校舎そのものを観測対象にすることで、地震直後に「この校舎を避難所として使えるか」を数分で判断できる。工学部（建築）・理工学部（建築・機械）・生産工学部が担当する。": "Making the building that carries the station an object of observation in its own right means the question “can this building serve as an evacuation centre?” can be answered within minutes of an earthquake. The Colleges of Engineering (Architecture), Science & Technology (Architecture and Mechanical Engineering) and Industrial Technology handle this.",
"気象・熱中症環境　学校微気候ツイン": "Weather and Heat Stress — a microclimate twin for schools",
"各局の複合気象センサーから WBGT（暑さ指数）を算出し、屋上 1 点の観測を校庭・体育館へダウンスケーリングして部活動の判断を支援する。線状降水帯は、雨量計だけでなくインフラサウンドによる雷放電の方位交会と 2 周波 GNSS の可降水量を組み合わせて早期に検知する（サブテーマ G-6 / G-4 / DT-3・DT-4）。": "WBGT is computed from each station’s all-in-one weather sensor, and the single rooftop measurement is downscaled to the schoolyard and gymnasium to support decisions about club activities. Training rainbands are detected early not from rain gauges alone but by combining bearing intersection of lightning infrasound with precipitable water from the dual-frequency GNSS (sub-themes G-6 / G-4 / DT-3, DT-4).",
