" · 校舎 3D モデルによる日影と地表面被覆を考慮（DT-3）": " · shading and surface cover from a 3D model of the buildings (DT-3)",
"屋上に置いた 1 台の気象センサーの値を、校舎の日影・地表面（土／人工芝／アスファルト）・風の遮蔽から校庭の各地点へ配分する。同一校庭内で WBGT が 3〜4℃ 違うことがあり、屋上値だけでは部活動の可否を判断できない。": "The reading from one rooftop sensor is distributed across the schoolyard according to building shadows, surface cover (bare soil, artificial turf, asphalt) and wind sheltering. WBGT can differ by 3–4 °C within a single schoolyard, so the rooftop value alone cannot decide whether club activities should go ahead.",
"活動の判断支援": "Supporting activity decisions",
