"31 ℃ 以上": "31 °C and above",
"屋外での運動を原則中止。屋内も空調のない場所は中止": "Outdoor exercise should be cancelled, as should indoor activity in unair-conditioned spaces",
"積極的に休息。運動の合間に必ず給水": "Rest often and drink between every activity",
"21 ℃ 未満": "Below 21 °C",
"各付属校の顧問端末へ 10 分ごとに自校の値と校庭内分布を配信し、判断の記録を残す。全国 14 校の同一仕様データにより、地域差・時間帯差の統計解析が可能になる。": "Every ten minutes each affiliated school’s club advisers receive their own value and the distribution across their schoolyard, and the resulting decisions are logged. Because all 14 schools record to the same specification, regional and time-of-day differences can be analysed statistically.",
