"全 14 局に夜空輝度計（Unihedron SQM-LU-DL、視野 FWHM 約 20°）を天頂向きに設置し、全天カメラの恒星測光と相互較正する。人工光（光害）・月・雲・衛星コンステレーションの寄与を分離し、経年変化を測る（サブテーマ G-3 / DT-2）。": "A sky quality meter (Unihedron SQM-LU-DL, ~20° FWHM field) points at the zenith at every one of the 14 stations, cross-calibrated against stellar photometry from the all-sky cameras. The contributions of artificial light, the Moon, cloud and satellite constellations are separated, and long-term change is measured (sub-themes G-3 / DT-2).",
