"暗い局では雲が空を暗くし、明るい局では都市光を反射して空を明るくする（符号が逆転する）。この差を使えば、雲量の独立推定にも使える。": "At a dark station cloud darkens the sky; at a bright one it reflects city light and brightens it — the sign reverses. That difference can itself serve as an independent estimate of cloud cover.",
"明るさの寄与分離（": "Breakdown of the brightness (",
"自然夜空を基準とした超過分（等級）。衛星の寄与は 40 倍に拡大して表示": "Excess over a natural sky, in magnitudes. The satellite contribution is magnified 40× to make it visible.",
"人工光（光害）": "Artificial light (light pollution)",
"雲による都市光の反射": "City light reflected by cloud",
