"超過等級": "Excess magnitude",
"雲の反射": "Cloud reflection",
"衛星（×40）": "Satellites (×40)",
"軌道上の衛星・デブリによる散乱光は天頂の夜空輝度を自然値より約 1 % 高めうると推定されている（Kocifaj et al. 2021, MNRAS Letters）。1 % は 0.011 等に相当し、光害の数等という寄与に比べて小さいため、全国 14 点・長期の均質観測で月・雲・人工光を差し引いて初めて分離できる。": "Light scattered by satellites and debris in orbit is estimated to raise zenith sky brightness about 1 % above its natural value (Kocifaj et al. 2021, MNRAS Letters). One per cent is 0.011 mag — far smaller than the several magnitudes contributed by light pollution — so it can only be isolated by subtracting the Moon, cloud and artificial light from long, homogeneous records at all 14 sites.",
"夜間データの蓄積待ち。": "Waiting for night data to accumulate.",
"夜空輝度の経年トレンド（5 年分・デモ）": "Long-term trend in sky brightness (5 years, demo)",
"月・雲の寄与を除いた月平均値。負の傾きは空が明るくなっていることを示す": "Monthly means with the Moon and cloud contributions removed. A negative slope means the sky is getting brighter.",
"年": "Year",
"都心局（駿河台）で −0.021 等/年、内陸暗夜（長野）で −0.004 等/年。都市部の LED 化・再開発と、衛星コンステレーションの増加という二つの要因を、地域差から分離することを目指す。": "−0.021 mag/year at the city-centre station (Surugadai) and −0.004 mag/year at the inland dark site (Nagano). The aim is to separate two causes — the shift to LED lighting and redevelopment in cities, and the growth of satellite constellations — using the regional difference between them.",
