"。気象庁の数値予報 GPV は気象業務支援センターを通じて提供されるものを利用し、高層気象観測の速報値とあわせて用いる。地上 1.5 km 以下は各観測局の複合気象センサーの実測値で置き換えるため、学校屋上の観測網そのものが暗黒飛行（ダークフライト）計算の精度に効く。": ". JMA numerical forecast GPV is obtained through the Japan Meteorological Business Support Center and used together with preliminary upper-air soundings. Below 1.5 km the profile is replaced by each station’s own weather-sensor measurements, so the rooftop network itself directly affects the accuracy of the dark-flight calculation.",
"配信内容": "What is sent",
