"（−8 等より明るい火球、または残存質量 0.1 kg 以上の推定で発報）": " (issued for a fireball brighter than −8 mag, or an estimated surviving mass of 0.1 kg or more)",
"受け手の行動": "What the recipient does",
"該当区域の被害確認、学校への連絡、問い合わせ窓口の準備": "Check the area for damage, notify schools, and set up a point of contact for enquiries",
"観測が「情報」から「行動」へ変わる。ここが社会実装の要（G-7）": "This is where observation turns from information into action — the crux of real-world use (G-7)",
"誤報を避けるため、単独局の検出では発報しない。多点で軌跡が決まり、かつ残存質量の推定が閾値を超えた場合に限る。配信後に人が追認し、必要なら訂正を出す。": "To avoid false alarms, no alert is issued on a single-station detection. It requires a trajectory fixed by multiple stations and an estimated surviving mass above the threshold. After distribution a human confirms the result and issues a correction if needed.",
"インフラサウンドセンサー 2 台（基線約 60 m）の気圧波形、": "Pressure waveforms from two infrasound sensors on a ~60 m baseline, ",
"到達時刻・周期・振幅から AFTAC の周期–収量関係で音響エネルギーを独立推定": "The acoustic energy is estimated independently from arrival time, period and amplitude using the AFTAC period–yield relation",
" GJ</b>（Brown et al. 2002）": " GJ</b> (Brown et al. 2002)",
" GJ</b>（周期 ": " GJ</b> (period ",
" 倍　<span class=\"hint\">因子 2 以内で整合し、光学推定を裏づけた</span>": "×  <span class=\"hint\">agreeing to within a factor of two, corroborating the optical estimate</span>",
"独立な二つの物理から同じ答えが出るか。単独センサーの観測網にはできない検証": "Whether two independent pieces of physics give the same answer — a check no single-sensor network can make",
"音は光より約 15 分の 1 の速さで届くため、検証は通報の後になる。二つの推定が大きく食い違えば落下域を再計算して訂正を出す。": "Sound arrives about fifteen times more slowly than light, so this check comes after the alert. If the two estimates disagree badly, the fall zone is recomputed and a correction issued.",
"自治体からの回答": "Reply from the municipalities",
"山武市より「被害報告なし」。東金市も同様": "Sanmu reported no damage; so did Togane",
"回収捜索": "Recovery search",
"方法": "Method",
"確率密度の高い区画から順に、UAV による空撮と地上班の踏査を組み合わせる": "Working through the highest-probability cells first, combining UAV aerial imaging with ground survey",
"地域との連携": "Working with the community",
"付属校の生徒が地元での聞き取りと目撃情報の収集を担当する": "Students from the affiliated schools handle local interviews and collect eyewitness reports",
"通報が実際に機能したか。次の事象に向けた閾値と手順の見直し材料になる": "Whether the alert actually worked — the basis for revising thresholds and procedures before the next event",
"回収できた隕石は文理学部の地球科学で組成を分析し、突入前の日心軌道と突き合わせる。落下域の推定がどれだけ当たったかは、次の事象の精度評価にそのまま使える。": "Any meteorite recovered is analysed for composition by Earth Science in the College of Humanities & Sciences and compared with the pre-entry heliocentric orbit. How well the fall-zone estimate did feeds straight into the accuracy assessment for the next event.",
"起きていること": "What is happening",
"房総半島東部（茂原市付近）で、同じ場所に次々と対流セルが発生し、南北に並び始める": "Over the eastern Boso Peninsula near Mobara, convective cells keep forming in the same place and begin to line up north–south",
"この時点の観測": "What has been observed so far",
"<b>まだ何も観測されていない。</b>観測局は帯の西 26–69 km にあり、雨量計にも気圧にも変化はない": "<b>Nothing yet.</b> The stations are 26–69 km west of the band, and neither the rain gauges nor the barometers show anything.",
