"長さ ": "Length ",
" km・幅 ": " km, width ",
" km、房総半島東部を南北に走る": " km, running north–south across the eastern Boso Peninsula",
"帯の移動": "Movement of the band",
"方位 ": "Azimuth ",
"なぜ難しいか": "Why this is hard",
"線状降水帯は帯の直下でなければ雨量計に何も現れない。気象レーダーは捉えられるが、学校ごとの判断材料にはならない": "A training rainband registers on a rain gauge only directly beneath it. Weather radar can see it, but that is not something an individual school can act on.",
"この観測網が狙うのは、帯の直下にいなくても帯の発生を知ることである。手がかりは、帯の中で連続する雷放電が出す 0.6–14 Hz のインフラサウンドと、上空の水蒸気量である。": "What this network is after is knowing the band has formed without being underneath it. The clues are the 0.6–14 Hz infrasound from the continuous lightning inside the band, and the water vapour aloft.",
"インフラサウンドセンサー 2 台（基線約 60 m）の気圧波形、全 14 局": "Pressure waveforms from two infrasound sensors on a ~60 m baseline, at all 14 stations",
"検知したもの": "What was detected",
"0.6–14 Hz の雷放電音。10 分あたり <b>24 回</b>（この時点）": "Lightning sounds at 0.6–14 Hz: <b>24</b> per 10 min at this point",
"検知局": "Detecting stations",
" の 3 局": "",
"音源まで 26–62 km。<b>帯の直下にいない局が最初に捉えた</b>": "26–62 km from the sources. <b>Stations nowhere near the band caught it first.</b>",
"東〜東南東の方向で、雷を伴う対流が連続して起きている": "Convection with lightning is occurring continuously to the east and east-southeast",
"帯の軸まで": "Distance to the band axis",
"方位のばらつき": "Bearing spread",
"雷検知数（全期間）": "Lightning detections (whole episode)",
"雷 1 回だけでは意味がない。10 分あたり 30 回を超え、かつ到来方位が一点に集中していることが、次の段階に進む条件になる。": "A single lightning strike means nothing. Moving to the next stage requires more than 30 per 10 minutes and bearings concentrated on one direction.",
"5 局の到来方位（それぞれ ±": "Bearings from five stations (each ±",
"各局から方位線を引いて交会させ、雷放電ひとつひとつの位置を推定する": "Bearing lines are drawn from each station and intersected to locate each individual lightning discharge",
"音源が <b>長さ ": "The sources are confirmed to lie in a band <b>",
" km の帯状</b>に並ぶことを確認": " km</b> long",
