"到来方位の時間変化から、方位 ": "From how the bearings change with time: bearing ",
"° へ ": "° at ",
"単発の雷雲ではなく、線状に並んだ対流であること。どちらへ動くか": "That this is convection arranged in a line rather than an isolated thunderstorm — and which way it is moving",
"「線状に並んでいる」という空間配列こそが線状降水帯の定義に直結する。単独局のインフラサウンドでは方位しか出ないが、5 局を束ねると形が出る。これが全国アレイの意味である。": "The linear arrangement is precisely what defines a training rainband. Infrasound at one station gives only a bearing; five stations together give a shape. That is what the nationwide array is for.",
"帯の推定位置と雷放電の定位（地図）を見る →": "See the estimated band position and lightning locations on the map →",
"2 周波 GNSS の搬送波遅延から求めた可降水量（PWV）。全 14 局・5 分ごと": "Precipitable water (PWV) from the dual-frequency GNSS carrier-phase delay, at all 14 stations every five minutes",
"船橋局で <b>43 → 58 mm（＋35 %）</b>。1 時間で 10 % 以上の上昇": "At Funabashi, <b>43 → 58 mm (+35 %)</b> — a rise of more than 10 % in one hour",
"下層へ強い水蒸気の流入が続いている。線状降水帯が維持される条件": "A strong low-level moisture inflow is continuing, which is what keeps a training rainband alive",
"同時に見る量": "Measured alongside",
"地上気圧の低下（−6.2 hPa）、風向の south-westerly への揃い": "Falling surface pressure (−6.2 hPa) and winds converging on a south-westerly direction",
"帯が一過性ではなく、当面続く見込みであること": "That the band is not transient but likely to persist",
"原理": "Principle",
"国土地理院 GEONET で行われている GNSS 気象学と同じ。それを学校屋上で密に行う（G-5）": "The same GNSS meteorology done on GSI’s GEONET, but carried out densely on school rooftops (G-5)",
"可降水量 PWV": "Precipitable water PWV",
"PWV mm ／ 気圧 −945 hPa": "PWV, mm / pressure −945 hPa",
