"雷（音）は「いま起きていること」を、可降水量（GNSS）は「これから続くかどうか」を示す。この二つが揃って初めて発報の根拠になる。": "The lightning sounds say what is happening now; the GNSS precipitable water says whether it will continue. Only with both together is there grounds for an alert.",
"判定方式": "Decision rule",
"6 条件すべての成立で「線状降水帯の可能性」を自動判定": "All six criteria must be met before a possible training rainband is flagged automatically",
"判定時刻": "Time of assessment",
"形成から 54 分。": "54 minutes after formation. ",
" 分後に外部の大雨情報が発表された": " minutes later the external heavy-rain bulletin was issued",
"使うセンサー": "Sensors used",
"インフラサウンド（雷）／2 周波 GNSS（可降水量）／複合気象センサー（気圧・雨量）": "Infrasound (lightning) / dual-frequency GNSS (precipitable water) / all-in-one weather sensor (pressure, rainfall)",
"発報してよい状態かどうか。1 つでも欠ければ「監視」に留める": "Whether an alert is justified. If even one criterion fails, the state stays at “monitoring”.",
"閾値": "Threshold",
"観測値": "Observed",
"担うセンサー": "Sensor",
"成立": "Met",
"不成立": "Not met",
"最初の 3 条件はインフラサウンドだけで満たせるが、それだけでは発報しない。水蒸気（GNSS）と気圧（気象センサー）の裏づけを必須にすることで、花火・爆発音・工事音による誤発報を防ぐ。": "The first three criteria can be met by infrasound alone, but that alone does not trigger an alert. Requiring corroboration from water vapour (GNSS) and pressure (weather sensor) prevents false alarms from fireworks, explosions and construction noise.",
"配信先（自治体）": "Recipients (municipalities)",
"千葉県 山武市・東金市・茂原市 の防災担当": "Disaster managers of Sanmu, Togane and Mobara, Chiba",
