"登校時間帯の変更、部活動の中止、屋外行事の延期": "Shifting arrival times, cancelling club activities, postponing outdoor events",
"各校が自分の位置と帯の位置を突き合わせて判断できる": "Each school can compare its own location with the band’s and decide for itself",
"気象庁の情報を置き換えるものではない。学校ごとに「自校がその帯の進路に入るか」を早く知るための補助であり、判断の記録を残して事後に検証する。": "This does not replace JMA information. It is an aid so that each school learns early whether it lies in the band’s path, and the decisions taken are logged for later review.",
