"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">stations</span>                <span class=\"c\"># 14局の諸元・稼働状態</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">stations</span>                <span class=\"c\"># specs and status of the 14 stations</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">stations</span>/{id}/status     <span class=\"c\"># 機材別の稼働・観測モード</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">stations</span>/{id}/status     <span class=\"c\"># status and mode per instrument</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">events</span>?from=&to=&min_mag= <span class=\"c\"># 火球・流星カタログ</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">events</span>?from=&to=&min_mag= <span class=\"c\"># fireball and meteor catalogue</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">events</span>/{id}              <span class=\"c\"># 軌跡・軌道・エネルギー・落下域</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">events</span>/{id}              <span class=\"c\"># trajectory, orbit, energy, fall zone</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">events</span>/{id}/lightcurve   <span class=\"c\"># 局別の光度曲線</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">events</span>/{id}/lightcurve   <span class=\"c\"># light curves by station</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">events</span>/{id}/spectrum     <span class=\"c\"># 分光（要 第3層）</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">events</span>/{id}/spectrum     <span class=\"c\"># spectra (Tier 3 required)</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">reentry</span>/forecast         <span class=\"c\"># 再突入予報（TLE 由来）</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">reentry</span>/forecast         <span class=\"c\"># re-entry forecasts (from TLE)</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">infrasound</span>/events        <span class=\"c\"># 音響イベントと定位結果</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">infrasound</span>/events        <span class=\"c\"># acoustic events and locations</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">infrasound</span>/{id}/waveform <span class=\"c\"># 波形（要 第3層）</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">infrasound</span>/{id}/waveform <span class=\"c\"># waveforms (Tier 3 required)</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">weather</span>?station=&res=1min <span class=\"c\"># 気象 1 分値・WBGT</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">weather</span>?station=&res=1min <span class=\"c\"># 1-minute weather and WBGT</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">skybrightness</span>?station=    <span class=\"c\"># 夜空輝度（SQM）</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">skybrightness</span>?station=    <span class=\"c\"># night sky brightness (SQM)</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">tec</span>?station=              <span class=\"c\"># 電離圏 TEC（2周波GNSS）</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">tec</span>?station=              <span class=\"c\"># ionospheric TEC (dual-frequency GNSS)</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">structure</span>/{id}/modes      <span class=\"c\"># 校舎固有振動数（要 第2層）</span>\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">structure</span>/{id}/modes      <span class=\"c\"># building natural frequencies (Tier 2 required)</span>\n",
"<span class=\"m\">GET</span> /api/v1/<span class=\"k\">alerts</span>                    <span class=\"c\"># 発報履歴</span>\n\n": "<span class=\"m\">GET</span> /api/v1/<span class=\"k\">alerts</span>                    <span class=\"c\"># alert history</span>\n\n",
