"このデモについて": "About This Demo",
"令和9年度 日本大学特別研究の申請に向けた、観測ポータル「ソラ」のデモ版である。観測網の設計は申請書のとおりで、表示されている観測値とイベントは一部模擬データである。気象庁のひまわり衛星画像と天気図は実データを気象庁のサーバーから取得している。": "A demonstration version of the SORA observation portal, prepared for the FY2027 Nihon University Special Research application. The network design is as given in the application; some of the readings and events shown are simulated. The Himawari satellite imagery and surface charts are real data fetched from JMA servers.",
"実データ（申請書に基づく）": "Real data (from the application)",
"このデモで正確に反映している内容": "What this demo reproduces faithfully",
"観測局 14 局の名称・所在地・座標・設置機関（大学キャンパス拠点 7 局／付属校拠点 7 局）。生産工学部は津田沼・実籾の両キャンパスを津田沼局が代表する": "The names, locations, coordinates and hosts of all 14 stations (7 university campus sites, 7 affiliated school sites). For the College of Industrial Technology, the Tsudanuma station represents both the Tsudanuma and Mimomi campuses.",
"SWIR 冷却カメラの設置局（船橋・湘南・郡山・三島）": "Which stations have the cooled SWIR camera (Funabashi, Shonan, Koriyama, Mishima)",
"全局共通のフル構成（機材の型式・仕様・価格帯・用途）": "The full configuration common to every station — models, specifications, price range and purpose",
"視野円の算出（高度 100 km を仰角 30° 以上で見込める地表半径 ": "The field circles (the ground radius from which 100 km altitude is seen above 30° elevation, ",
"日本の都道府県境界（国土数値情報を簡略化したデータ）": "Japan’s prefectural boundaries (simplified National Land Numerical Information data)",
"全国 1,893 市区町村の境界：国土数値情報 行政区域データ（国土交通省, N03）を簡略化したもの。局所マップを拡大したときに、必要な都道府県の分だけを読み込んで表示する": "Boundaries of all 1,893 Japanese municipalities: simplified from the National Land Numerical Information administrative area data (MLIT, N03). Only the prefectures needed are loaded, as you zoom into a local map.",
"サブテーマ G-1〜G-8 とデジタルツイン DT-1〜DT-7 の対応": "The mapping between sub-themes G-1 to G-8 and digital twins DT-1 to DT-7",
"恒星 9,096 個の位置・等級・色指数：エール輝星星表 第5版（BSC5, Hoffleit & Warren 1991, CDS/VizieR V/50）": "Positions, magnitudes and colour indices of 9,096 stars: Yale Bright Star Catalogue, 5th edition (BSC5, Hoffleit & Warren 1991, CDS/VizieR V/50)",
"星座線 752 本：IAU 公式星座図形（Stellarium「modern_iau」スカイカルチャー, CC BY-SA 4.0）": "752 constellation lines: the official IAU constellation figures (Stellarium “modern_iau” sky culture, CC BY-SA 4.0)",
"天の川：Tycho-2 の V<11.5 星数密度（Hog et al. 2000, CDS I/259）を 1 度グリッドに集計したもの": "The Milky Way: Tycho-2 star densities for V < 11.5 (Høg et al. 2000, CDS I/259) binned onto a one-degree grid",
"物理関係式：Brown et al. (2002) の Er–E 関係、AFTAC の周期–収量関係、Ono & Tonouchi (2014) の WBGT 推定式、Bortle (2001) の空の等級": "The physical relations: the Er–E relation of Brown et al. (2002), the AFTAC period–yield relation, the WBGT formula of Ono & Tonouchi (2014), and the sky classes of Bortle (2001)",
"気象庁 ひまわり衛星画像（可視 B03・赤外 B13・水蒸気 B08・真彩色）と地上天気図：気象庁のサーバーから実データを取得して観測局マップに重ねている": "JMA Himawari imagery (visible B03, infrared B13, water vapour B08, true colour) and surface charts: real data fetched from JMA servers and overlaid on the station map",
"流星群の活動期間・極大日・極大時の太陽黄経・ZHR：IMO Meteor Shower Calendar / IMO Working List（主要 16 群）": "Shower activity periods, peak dates, solar longitude at maximum and ZHR: IMO Meteor Shower Calendar / IMO Working List (the 16 major showers)",
"防災科学技術研究所（NIED）の公開観測網との対応：K-NET・KiK-net／Hi-net／F-net／S-net・DONET／J-RISQ／J-SHIS／V-net／クライシスレスポンス": "The correspondence with NIED’s open observation networks: K-NET / KiK-net, Hi-net, F-net, S-net / DONET, J-RISQ, J-SHIS, V-net and Crisis Response",
"発光スペクトルの線同定と相対強度：実際に取得された流星スペクトル（S. Abe et al. 2000 のしし座流星群スペクトルほか）の代表例に合わせて構成。回折格子は 600 本/mm を想定": "Line identifications and relative intensities in the emission spectra, built to match representative real meteor spectra (the Leonid spectra of S. Abe et al. 2000, among others). A 600 lines/mm grating is assumed.",
"スペースデブリの分子（酸化物）バンド AlO・CN・TiO・FeO の同定、励起温度、発光開始→アブレーション→爆発→分裂→終端の推移：Watanabe, Abe, Arima & Hanayama (ACM 2026) による LM-3B 第2段の再突入分光観測": "The identification of the AlO, CN, TiO and FeO molecular (oxide) bands in space debris, their excitation temperatures, and the progression from first light through ablation, explosion and break-up to the terminal point: from the LM-3B second-stage re-entry spectroscopy of Watanabe, Abe, Arima & Hanayama (ACM 2026)",
"線状降水帯の参照事象：2023 年 9 月 8 日に千葉県で発生し気象庁が「顕著な大雨に関する情報」を発表した事例": "The reference training-rainband event: the case of 8 September 2023 in Chiba Prefecture, for which JMA issued its “significant heavy rainfall” bulletin",
