"緑の実線は各局のインフラサウンド到来方位（破線は方位のばらつき）。点は雷放電の推定位置で、色は発生時刻。青の破線は 3 時間後の帯の位置。市区町村の境界は国土数値情報 行政区域データ（国土交通省）による": "Green solid lines are the infrasound bearings from each station; dashed lines show the spread in bearing. The dots are estimated lightning positions, coloured by time. The blue dashed outline is where the band will be in three hours. Municipal boundaries come from the National Land Numerical Information administrative area data (MLIT). Municipality names are shown in Japanese, as in the source data.",
