"千葉県 山武市・東金市・茂原市／県東部の付属校 3 校": "Sanmu, Togane and Mobara in Chiba, and three affiliated schools in the east of the prefecture",
"帯の直下の降水量は、方位交会で求めた雷放電の密度と船橋局の実測から推定した値であり、レーダー観測の代替ではない。運用では気象庁レーダー・解析雨量と突き合わせて検証する。": "Rainfall directly beneath the band is inferred from the lightning density obtained by bearing intersection together with the Funabashi measurements; it is not a substitute for radar. In operation it would be verified against JMA radar and analysed precipitation.",
