"<span class=\"sm\">帯の直下でなくても 50–70 km 先を検知。方位交会で位置・長さ・向き・移動が出る。<b>最も早い</b></span>": "<span class=\"sm\">Detects at 50–70 km without being under the band; bearing intersection gives position, length, orientation and movement. <b>The earliest signal.</b></span>",
"2 周波 GNSS（可降水量）": "Dual-frequency GNSS (precipitable water)",
"観測局上空の水蒸気総量（PWV）": "The total water vapour above the station (PWV)",
"<span class=\"sm\">降水が始まる前に水蒸気の流入が現れる。GEONET と同じ原理を学校屋上で実施</span>": "<span class=\"sm\">The moisture inflow appears before any rain does. The same principle as GEONET, carried out on school rooftops.</span>",
"雨量・気圧・風向風速・気温": "Rainfall, pressure, wind and temperature",
"<span class=\"sm\">最も確実だが、帯が到達してからでないと分からない。判定の確定と検証に使う</span>": "<span class=\"sm\">The most certain, but only once the band arrives. Used to confirm and verify the assessment.</span>",
"雲底の様子と発雷の閃光": "The cloud base and the flash of a discharge",
"<span class=\"sm\">夜間は発雷の光でインフラサウンドの検知を裏づけ、誤検知（工事音・爆発音）を排除できる</span>": "<span class=\"sm\">At night the flash corroborates the infrasound detection and rules out false alarms from construction or explosions.</span>",
"インフラサウンドは火球の衝撃波（G-1）・火山噴火（G-4）と同じ装置・同じ波形処理を使う。一つのセンサー網が、宇宙起源の災害と気象災害の双方に効くことが本観測網の設計思想である。": "The infrasound here uses the same instrument and the same waveform processing as fireball shock waves (G-1) and eruptions (G-4). That a single sensor network serves both space-origin and meteorological hazards is the design principle of this project.",
"海底から電離圏までの結合と、各層を観測するセンサー": "The coupling from seafloor to ionosphere, and the sensor that watches each layer",
