"・大気重力波：0.8–4 mHz 帯の気圧変動を 2 局のインフラサウンドで観測\n": "· Atmospheric gravity waves: pressure variation in the 0.8–4 mHz band, observed by infrasound at two stations\n",
"・微動計：全 14 局で P 波を検知、校舎の固有振動数に有意な変化なし\n": "· Microtremor sensors: P waves detected at all 14 stations, with no significant change in building natural frequencies\n",
"・これらを入力としたサロゲートモデルの推論結果（推論時間 12 ms）\n\n": "· The surrogate model’s inference from these inputs (inference time 12 ms)\n\n",
"■ 注意\n": "■ Please note\n",
"・本推定は気象庁の津波警報・注意報を置き換えるものではありません。避難は警報に従ってください。\n": "· This estimate does not replace JMA tsunami warnings or advisories. Follow the official warnings when evacuating.\n",
"・本推定は警報の後に「どれくらいの規模か」を独立に見積もり、避難の継続判断を補うためのものです。\n": "· It is intended to add, after a warning, an independent estimate of how large the tsunami will be, to help decide whether to stay evacuated.\n",
"・推定には ±": "· The estimate carries an uncertainty of ±",
" m の不確かさがあります。": " m.",
"Web ポータル（全文・根拠と注意を必ず併記）": "Web portal (full text, always with the basis and the caveats)",
"地震・津波　全センサーの統合とデジタルツイン": "Earthquakes and Tsunamis — all sensors combined, and the digital twin",
"海底の変動は、地殻を揺らし、大気に音波と重力波を放ち、電離圏の電子密度を変える。本観測網は微動計・インフラサウンド・気象センサー・2 周波 GNSS を同一地点に揃えているため、この一連の結合を一つの局で追える。地震そのものは気象庁と防災科研の観測網が担うので、本観測網は「その後に大気と電離圏で何が起きたか」を受け持つ（サブテーマ G-4・G-5・G-6 / DT-4・DT-5・DT-6）。": "Motion of the seafloor shakes the crust, radiates sound and gravity waves into the atmosphere, and alters the electron density of the ionosphere. Because this network puts a microtremor sensor, infrasound sensors, a weather sensor and a dual-frequency GNSS receiver at the same spot, that whole chain of coupling can be followed from a single station. The earthquake itself is the business of JMA and NIED; this network takes on what happens afterwards in the atmosphere and the ionosphere (sub-themes G-4, G-5, G-6 / DT-4, DT-5, DT-6).",
"直近の地震": "Most recent earthquake",
"電離圏の応答": "Ionospheric response",
"TEC に音波共振（": "Acoustic resonance in TEC (",
" mHz）": " mHz)",
"推定沿岸波高": "Estimated coastal wave height",
"実測 ": "measured ",
" m（": " m (",
"局 継続使用可": "stations fit for continued use",
"固有振動数の低下は 5 % 未満": "Natural frequencies dropped by less than 5 %",
"鉛直方向の結合とセンサーの対応": "Vertical coupling and the sensors that watch it",
"一つの事象が層を越えて伝わる過程を、どのセンサーがどの層を見ているかとして示す（DT-4・DT-5・DT-6 の接点）": "How one event propagates across the layers, laid out by which sensor watches which layer — where DT-4, DT-5 and DT-6 meet",
"デジタルツインは可視化だけの仕組みではない。ここでは、観測された TEC の擾乱と大気重力波の振幅から津波の規模を逆算し、その結果を検潮所の実測と突き合わせて係数を更新する、という同化の流れそのものを指す。層ごとに別の研究室が持っていたデータを、同一地点・同一時刻で並べられることが本観測網の要点である。": "A digital twin is not merely a way of visualising things. Here it means the assimilation loop itself: inferring the size of the tsunami from the observed TEC disturbance and gravity-wave amplitude, then comparing the result with tide-station measurements and updating the coefficients. What matters is that data which used to sit in separate laboratories, layer by layer, can now be lined up at one place and one instant.",
"この事象では検知なし": "Not detected in this event",
" 分　": " min  ",
"震央と検知した観測局": "Epicentre and the stations that detected it",
"✕ が震央。破線は震央と検知局を結ぶ（色＝センサーの種類）。拡大すると市区町村の境界を表示する（国土数値情報 行政区域データ）": "The ✕ marks the epicentre; dashed lines join it to the detecting stations, coloured by sensor type. Municipal boundaries appear as you zoom in (National Land Numerical Information administrative area data). Municipality names are shown in Japanese, as in the source data.",
"<i style=\"background:var(--c-warn)\"></i>微動計": "<i style=\"background:var(--c-warn)\"></i>Microtremor",
"<i style=\"background:var(--c-sky)\"></i>2 周波 GNSS（TEC）": "<i style=\"background:var(--c-sky)\"></i>Dual-frequency GNSS (TEC)",
"<i style=\"background:var(--c-infra)\"></i>インフラサウンド": "<i style=\"background:var(--c-infra)\"></i>Infrasound",
"検知の時系列": "Detection timeline",
" 件・": " events · ",
" JST の地震": " JST earthquake",
"電離圏 TEC の時系列": "Ionospheric TEC time series",
"2 周波 GNSS。地震発生を 0 分とする": "Dual-frequency GNSS, with the earthquake at 0 min",
"共振成分（拡大）": "Resonance component (magnified)",
"音波共振": "Acoustic resonance",
"共振（+8 分）は海面が動いたことを示し、ホール（+19 分）はその大きさを含む。前者は早く、後者は確からしい。両方を見ることで早さと確度を両立させる。": "The resonance at +8 min says the sea surface moved; the hole at +19 min carries how much. The first is fast, the second is reliable. Watching both gives speed and confidence together.",
"津波規模の推定と検証": "Estimating and verifying the tsunami size",
"TEC 最大減少": "Maximum TEC depletion",
"減少率": "Depletion rate",
