"現在の判定 <b style=\"color:var(--c-ok)\">平常</b>": "Current assessment <b style=\"color:var(--c-ok)\">normal</b>",
"サロゲートモデルによる即時推定と通報": "Immediate estimation and alerting with a surrogate model",
"観測が入った瞬間に推定して配信する。数値計算そのものは間に合わないため、事前に学習させた代理モデルに置き換える": "The estimate is made and sent the instant the observations arrive. Since the full numerical computation cannot keep up, it is replaced by a model trained in advance.",
"津波の伝播・浸水は非線形長波方程式を解いて求めるが、高解像度で計算すると数十分から数時間かかり、避難の判断には間に合わない。そこで断層すべりと海底地形の組み合わせを変えた多数のシナリオをあらかじめ計算しておき、その入出力関係を学習した<b>サロゲートモデル（代理モデル）</b>に置き換える。推論は 12 ミリ秒で終わるので、観測が届いた瞬間に沿岸波高・到達時刻・不確かさを返せる。デジタルツインが「見せるだけ」で終わらないのは、この置き換えがあるためである。": "Tsunami propagation and inundation are obtained by solving the nonlinear long-wave equations, but at high resolution that takes tens of minutes to hours — far too slow for an evacuation decision. So many scenarios are computed in advance, varying fault slip and bathymetry, and a <b>surrogate model</b> trained on that input–output relation takes their place. Inference finishes in 12 milliseconds, so coastal wave height, arrival time and uncertainty come back the moment the observations land. This substitution is what keeps the digital twin from being merely a display.",
"サロゲートモデルの諸元": "Surrogate model specifications",
"事前学習は学内クラウドで行い、推論は各局のエッジ計算機と中央の両方で走らせる": "Training runs on the university cloud; inference runs both on the edge computers at each station and centrally",
"24 次元（TEC 減少率・共振振幅・大気重力波振幅・気圧変動・P 波初動・到達時刻差・震源の緯度経度深さ・Mw）": "24 dimensions (TEC depletion rate, resonance amplitude, gravity-wave amplitude, pressure change, P-wave first motion, arrival-time differences, hypocentre latitude, longitude and depth, and Mw)",
"6 次元（沿岸波高・到達時刻・浸水域の広がり・それぞれの不確かさ）": "6 dimensions (coastal wave height, arrival time, extent of inundation, and the uncertainty of each)",
"学習データ": "Training data",
"断層すべり分布と潮位条件を変えた数値計算 <b>18,000 シナリオ</b>（南海トラフ・日本海溝・日本海東縁）": "<b>18,000 scenarios</b> computed numerically with varying fault slip distributions and tide conditions (Nankai Trough, Japan Trench, eastern margin of the Sea of Japan)",
"シナリオの 15 % を検証用に残し、沿岸波高の平均絶対誤差 <b>0.31 m</b>": "15 % of the scenarios were held out for validation, giving a mean absolute error of <b>0.31 m</b> in coastal wave height",
"推論時間": "Inference time",
"<b>12 ms</b>（中央）／ 38 ms（エッジ計算機）": "<b>12 ms</b> centrally, 38 ms on the edge computers",
"更新頻度": "Update rate",
"平常時は 30 秒ごと、地震検知後は 1 秒ごと": "Every 30 s normally, every 1 s once an earthquake is detected",
"再学習": "Retraining",
"事象ごとに実測（検潮所・S-net）と突き合わせ、四半期ごとに係数を更新": "Each event is compared with measurements from tide stations and S-net, and the coefficients are updated quarterly",
"限界": "Limitations",
"学習範囲の外（想定外の断層・遠地津波）では外挿になるため、不確かさを大きく出して人の判断に委ねる": "Outside the training range — an unanticipated fault, or a distant tsunami — the model is extrapolating, so it reports a large uncertainty and defers to human judgement",
"フェイルセーフ": "Fail-safes",
"誤報を出さないための設計。危機管理学部・法学部と整備する": "Designed to prevent false alarms, developed with the Colleges of Risk Management and Law",
"条件": "Condition",
"扱い": "Handling",
"単独センサーのみの検知": "Detection by a single sensor only",
"発報しない（監視状態に留める）": "No alert; the state stays at monitoring",
"気象庁の警報と矛盾": "Conflict with a JMA warning",
"<b>気象庁の警報が優先</b>。本推定は参考値として併記するに留める": "<b>The JMA warning takes precedence.</b> This estimate is shown only alongside it, for reference.",
"学習範囲外の入力": "Input outside the training range",
"不確かさを拡大して出力し、自動配信は止めて人の確認へ回す": "The uncertainty is widened, automatic distribution is halted, and the case goes to a person for review",
"推論時間が閾値超過": "Inference time exceeds the threshold",
"前回の推定を保持し、劣化モード（単純な経験式）に切り替える": "The previous estimate is kept and the system falls back to a degraded mode using a simple empirical formula",
"配信後に推定が変わった": "The estimate changes after distribution",
"訂正を同じ経路で必ず配信する。取り消しは行わず訂正として残す": "A correction always goes out by the same channel. Nothing is retracted; the correction stands on the record.",
"SNS への投稿": "Posting to social media",
"自動投稿はしない。下書きを生成し、人が確認してから投稿する": "Never automatic. A draft is generated and a person reviews it before it is posted.",
"SNS は自動投稿しない。この下書きを担当者が確認し、必要なら手を入れてから投稿する。未確定の推定値を含むため、取り消しではなく訂正で運用する。": "Nothing is posted to social media automatically. A staff member reviews this draft, edits it if necessary, and then posts it. Because it contains a provisional estimate, the practice is to issue a correction rather than delete.",
"どの経路でも「気象庁の警報が優先する」ことと不確かさを必ず併記する。文面は法学部・危機管理学部と整備した定型から自動生成する。": "Every channel carries both the uncertainty and the statement that JMA warnings take precedence. The wording is generated automatically from templates prepared with the Colleges of Law and Risk Management.",
