"常時微動から同定した 1 次固有振動数を地震前後で比較する。低下が 5 % を超えたら「点検要」を自動発報する": "The first natural frequency identified from ambient vibration is compared before and after the earthquake. A drop of more than 5 % automatically raises an “inspection required” notice.",
"設置校": "School",
"点検要": "Inspection required",
"固有振動数は剛性の平方根に比例するため、低下率は構造的な損傷の指標になる。学校は多くの自治体で避難所に指定されており、地震直後に「この校舎を使ってよいか」を数分で答えられることの意味は大きい。工学部（建築）・理工学部（建築・機械）・生産工学部が担当する。": "Natural frequency scales with the square root of stiffness, so the size of the drop indicates structural damage. Schools are designated evacuation centres in many municipalities, and being able to answer “can this building be used?” within minutes of an earthquake matters a great deal. The Colleges of Engineering (Architecture), Science & Technology (Architecture and Mechanical Engineering) and Industrial Technology handle this.",
"防災科学技術研究所（NIED）の公開データとの突き合わせ": "Cross-checking against NIED open data",
"本観測網だけでは閉じない。既存の基盤観測網と突き合わせて初めて検証になる": "This network does not stand alone. Only by checking against the established national networks does verification become possible.",
