"海上保安庁 第三管区（航行警報の参考）": "Japan Coast Guard, 3rd Regional Headquarters (for navigational warnings)",
"炭素系アブレータ由来の C₂ と CN が卓越": "C₂ and CN from the carbon ablator dominate",
"弾道再突入体と判定": "Identified as a ballistic re-entry vehicle",
"分子バンド": "Molecular bands",
"参考": "Reference",
"弾道再突入体のスペクトルは、炭素系アブレータ（カーボンフェノリック）をもつ再突入体に一般に期待される": "The ballistic re-entry spectrum is built from the chemical species generally expected of a re-entry vehicle with a carbon-phenolic ablative heat shield. ",
"化学種から構成した想定値である。C₂ スワンバンドと CN の同定、および Al I が弱いことの意味づけは、": "The identification of the C₂ Swan bands and CN, and the significance of a weak Al I, follow comparison with the measured spectra of ",
"「はやぶさ」カプセル（S. Abe et al. 2011, PASJ）およびロケットデブリ（Watanabe et al., ACM 2026）の": "the Hayabusa capsule (S. Abe et al. 2011, PASJ) and of rocket debris (Watanabe et al., ACM 2026). ",
"実測スペクトルとの対比による。表示している波形そのものはデモ用の合成スペクトルであり、実観測データではない。": "The trace shown is a synthetic spectrum made for this demo, not a real observation.",
"再突入天体の光学・分光・音響観測": "Re-entering Objects — optical, spectroscopic and acoustic observation",
"公開軌道要素から再突入を予報し、光学・SWIR・分光・インフラサウンドで実観測する。破片化の過程と大気への金属注入量を地上から直接推定する。速度・経路角・継続時間・スペクトルの組み合わせで、自然火球・軌道デブリ・弾道飛翔体を区別する（サブテーマ G-2 / DT-1）。": "Re-entries are forecast from public orbital elements and then actually observed in the optical, SWIR, spectroscopic and infrasound bands. The break-up sequence and the metal injected into the atmosphere are estimated directly from the ground. The combination of speed, path angle, duration and spectrum separates natural fireballs, orbital debris and ballistic projectiles (sub-themes G-2 / DT-1).",
"弾道飛翔体（想定シナリオ）": "Ballistic projectile (scenario)",
"軌道デブリ（衛星の再突入）": "Orbital debris (satellite re-entry)",
"軌道デブリ（1〜3°）よりはるかに急 ＝ 弾道軌道の特徴": "Far steeper than orbital debris (1–3°) — characteristic of a ballistic trajectory",
"落下点の独立推定": "Independent estimate of the splashdown point",
"8 局のインフラサウンド到達時刻差の交会による": "By intersecting infrasound arrival-time differences from eight stations",
"本観測網の落下時刻": "Splashdown time from this network",
"（推定誤差 ± ": " (estimated error ± ",
"推定落下点": "Estimated splashdown point",
"落下点の誤差": "Splashdown point error",
" km</b>（音響交会）／ ± 6.1 km（光学の軌跡延長）": " km</b> (acoustic intersection) / ± 6.1 km (optical trajectory extrapolation)",
"海域": "Sea area",
"防衛省の予測との差": "Difference from the MoD prediction",
"大気へのアブレーション質量": "Mass ablated into the atmosphere",
"<b>推定落下点</b><span class=\"mt-d\">": "<b>Estimated splashdown point</b><span class=\"mt-d\">",
"地上軌跡・暗黒飛行・推定落下点": "Ground track, dark flight and estimated splashdown point",
"実線は発光区間、赤の破線は発光終了（高度 27 km）から海面までの暗黒飛行。✕ が推定落下点。市区町村の境界は国土数値情報 行政区域データ（国土交通省）による": "The solid line is the luminous segment; the red dashed line is the dark flight from the end of emission at 27 km down to the sea. The ✕ marks the estimated splashdown point. Municipal boundaries come from the National Land Numerical Information administrative area data (MLIT). Municipality names are shown in Japanese, as in the source data.",
"22 秒の発光。急な経路角のため短時間で深く入り、減速が強い区間で最大光度になる": "A 22-second emission. The steep path angle takes it deep quickly, and peak brightness comes where deceleration is strongest.",
"自然火球は 0.5〜8 秒、軌道デブリは 20〜120 秒。22 秒という長さは軌道デブリに近いが、経路角 38° と速度 5.9 km/s の組み合わせはどちらとも重ならない。急な経路角では大気の密度が急に増すため、光度曲線の立ち上がりが鋭くなる。": "Natural fireballs last 0.5–8 s and orbital debris 20–120 s. At 22 s the duration is close to orbital debris, but the combination of a 38° path angle and 5.9 km/s overlaps neither. A steep path angle means the air density rises abruptly, which sharpens the leading edge of the light curve.",
"J-ALERT との関係": "Relation to J-ALERT",
"警報を出すのは国。本観測網は「落ちた場所と時刻」を後から独立に確かめる": "Issuing the warning is the government’s job. This network independently establishes, afterwards, where and when it came down.",
"本観測網は警報を出さない": "This network issues no warnings",
"弾道飛翔体の探知・警報は、防衛省の早期警戒衛星とレーダー、内閣官房・消防庁の J-ALERT が担う。": "Detection and warning for ballistic projectiles rest with the Ministry of Defense’s early-warning satellites and radar, and with J-ALERT run by the Cabinet Secretariat and the Fire and Disaster Management Agency. ",
"本観測網にその役割はなく、代われるものでもない。できるのは、警報が出たあとに残る「結局どこへ落ちたのか」": "This network has no part in that and could not substitute for it. What it can do is answer, from optical and acoustic measurement, the question that remains once the warning has gone out: where did it actually come down? ",
"という問いに、光学と音の実測から独立した答えを出すことである。自治体と学校が屋外活動の再開を判断するとき、": "That independent answer is something municipalities and schools can use when deciding whether to resume outdoor activity, ",
"また航行警報の解除を検討するときに、この独立推定が材料になる。": "and when considering whether to lift a navigational warning.",
