"落下海域が陸から 210 km 沖と確認され、屋外活動を再開": "The splashdown area is confirmed as 210 km offshore, and outdoor activity resumes",
"警報・避難の判断は内閣官房・防衛省・消防庁の発表が優先する。本観測網の推定値は、": "Announcements by the Cabinet Secretariat, the Ministry of Defense and the Fire and Disaster Management Agency take precedence for any warning or evacuation decision. This network’s estimates are always ",
