"警報中": "During the warning",
"屋内退避。登校時間帯なら通学路で足止めが生じる": "Shelter indoors; if it falls during the journey to school, pupils are stranded en route",
"（観測網の役割なし。国の警報に従う）": "(no role for the network; follow the national warning)",
"落下直後": "Immediately after",
"「どこに落ちたか」が分からないまま待機が続く": "Waiting continues with no word on where it came down",
"再突入発光の検出と、軌跡からの落下点の速報（+64 秒）": "Detection of the re-entry emission and a first splashdown estimate from the trajectory (+64 s)",
"報道や発表を待つ時間が長く、再開の判断ができない": "The wait for news or an official statement is long, and no decision to resume can be made",
"音響交会による落下点の確定（± 3.8 km）と落下時刻（± 2.4 秒）": "The splashdown point fixed by acoustic intersection (± 3.8 km) and its time (± 2.4 s)",
"再開": "Resuming",
"屋外活動・部活動・下校をいつ戻すかの判断": "Deciding when to restore outdoor activity, clubs and the journey home",
"陸域からの距離と、破片が陸へ到達しないことの根拠": "The distance from land, and the evidence that no fragment reaches it",
"事後": "Afterwards",
"記録が残らず、次の訓練に活かせない": "Nothing is recorded, so the next drill learns nothing",
"波形・映像・解析の一式を保存し、訓練の検証材料にする": "The waveforms, imagery and analysis are kept as material for reviewing the drill",
"茨城・福島・千葉の付属校 3 校を対象に、J-ALERT の受信から再開判断までを通した訓練を": "A drill running from the J-ALERT message through to the decision to resume is designed jointly with the College of Risk Management, ",
"危機管理学部と合同で設計する。観測網は訓練のたびに「実際に何秒で何が分かったか」を記録し、手順の見直しに使う。": "for three affiliated schools in Ibaraki, Fukushima and Chiba. Each time, the network records exactly how many seconds it took to learn what, and that is used to revise the procedure.",
