"地上に降ってくる宇宙線ミューオンの数は、いつもほぼ一定に見える。しかし実際には頭上の大気の量（気圧）と": "The number of cosmic-ray muons reaching the ground looks all but constant. In fact it drifts slightly with the amount of air overhead (the pressure), ",
"成層圏の気温、そして太陽活動でわずかに上下しており、その幅は数 % しかない。": "with the temperature of the stratosphere and with solar activity — but only by a few per cent. ",
"受光面 25 cm² の検出器 1 台では 1 分あたりの計数が 30 前後しかなく、統計のばらつき（±√N ≒ ": "A single detector with a 25 cm² collecting area records only about 30 counts a minute, so statistical scatter alone (±√N ≈ ",
"）だけで": ") makes it ",
"±17 % 揺れてしまう。つまり 1 台・短時間では原理的に見えない。": "swing by ±17 %. One unit over a short interval simply cannot see the effect. ",
"同じ装置を 14 局に置き、同じ局の気圧計で補正して 1 日ぶん足し合わせると、ばらつきは ±0.1 % まで下がり、": "Put the same instrument at 14 stations, correct each with its own barometer, and sum a full day, and the scatter falls to ±0.1 %; ",
"気圧効果もフォーブッシュ減少もはっきり数値として出る。この「数を増やして時間をかける」という手続きそのものが、": "both the barometric effect and Forbush decreases then emerge as clear numbers. That procedure — more detectors, longer integration — is itself ",
"観測網を持つことの意味であり、そのまま探究学習の教材になる（G-8）。": "what having a network means, and it makes a ready-made subject for inquiry-based learning (G-8).",
