"気圧が下がると計数は上がり、上がると下がる。補正するとこの逆相関が消えて平坦になり、": "When the pressure falls the count rises, and vice versa. Correcting for it removes that anti-correlation and flattens the curve, ",
"残った変動が太陽活動や大気上層の気温によるものになる。気圧計を同じ屋上に持っていることが、ここで効いてくる。": "leaving variation that comes from solar activity and from the temperature of the upper atmosphere. Having a barometer on the same roof is what makes this possible.",
