"NICT 宇宙天気予報・地磁気擾乱（Dst 指数）・本観測網の電離圏 TEC（G-5）": "NICT space-weather forecasts, geomagnetic disturbance (Dst index), and this network’s own ionospheric TEC (G-5)",
"宇宙天気の地上への影響を、学校の屋上で直接測れる": "The effect of space weather at ground level, measured directly from a school roof",
"フォーブッシュ減少は世界の中性子モニタ網で日常的に観測されている現象で、": "Forbush decreases are routinely observed by neutron monitor networks worldwide, ",
"同じものを安価な検出器を数多く置くことでも捉えられる。2 周波 GNSS の電離圏 TEC（DT-5）と同じ事象を別の物理で見ることになる。": "and the same thing can be caught by deploying many inexpensive detectors instead. It means seeing the same event as the dual-frequency GNSS ionospheric TEC (DT-5), through different physics.",
"ほかのセンサーと組み合わせて分かること": "What emerges when combined with the other sensors",
