"付属校 7 局": "The seven affiliated school stations",
"雷雲ガンマ線（TGE）とインフラサウンドの同時観測": "Simultaneous observation of thunderstorm gamma rays (TGE) and infrasound",
"雷は音と放射線の両方を出す。同じ屋上で両方を測れる観測網は多くない": "Lightning emits both sound and radiation. Few networks can measure both from the same roof.",
"発達した雷雲の中では電場によって電子が加速され、制動放射でガンマ線が出る。地上でこれを捉えたものを": "Inside a developed thundercloud, electrons are accelerated by the electric field and emit gamma rays as bremsstrahlung. Catching this at the ground is called ",
"雷雲ガンマ線（thunderstorm ground enhancement, TGE）と呼び、日本海側の冬季雷では日常的に観測されている。": "a thunderstorm ground enhancement (TGE), and it is observed routinely in the winter thunderstorms along the Sea of Japan coast. ",
"本観測網はインフラサウンドで雷放電の位置を、宇宙線計測器で放射線の増加を、同じ局で同時に記録できる。": "This network can record the position of the discharge with infrasound and the rise in radiation with the cosmic-ray detector, at the same station and the same moment. ",
"「放電の直前に増え、放電と同時に止まる」という時間関係を押さえられれば、雷雲内部の電場の状態を外から推定できる。": "Pinning down that timing — rising just before the discharge, stopping with it — allows the state of the field inside the cloud to be inferred from outside. ",
"TGE は数十 % に達することもあり、数 % の気圧効果と違って 1 台でもはっきり見える。": "A TGE can reach tens of per cent, so unlike the few-per-cent barometric effect it is plainly visible even on a single unit.",
