"日本では Enoto et al. (2017, <i>Nature</i>) が冬季雷に伴うガンマ線で光核反応を捉えるなど、": "In Japan, Enoto et al. (2017, <i>Nature</i>) caught photonuclear reactions in gamma rays from winter lightning, ",
"雷と高エネルギー現象の研究が進んでいる。本観測網の狙いはその追試ではなく、": "and work on lightning and high-energy phenomena continues. The aim here is not to repeat that but to build ",
"<b>雷を「音」と「放射線」の両方で同時に記録する多点網</b>をつくることにある。線状降水帯の検知（G-6）で用いる雷放電の": "<b>a multi-station network that records lightning in both sound and radiation at once</b>. The same event can be checked through different physics against the bearing intersection of lightning ",
"方位交会と、同じ事象を別の物理で確かめられる。": "used for training-rainband detection (G-6).",
