"（<a href=\"https://shop.accel-kitchen.com/items/131852452\" target=\"_blank\" rel=\"noopener\">shop.accel-kitchen.com/items/131852452</a>）。": "(<a href=\"https://shop.accel-kitchen.com/items/131852452\" target=\"_blank\" rel=\"noopener\">shop.accel-kitchen.com/items/131852452</a>). ",
"プラスチックシンチレータ 5×5×1 cm、SiPM 型光センサー、ESP32、OLED 表示、USB 給電、ブラウザで波形と計数を表示。": "A 5×5×1 cm plastic scintillator, SiPM optical sensor, ESP32, OLED display, USB power, with waveform and counts shown in a browser. ",
"中高生・大学初年次の教材として設計されており、組み立てそのものを探究学習に組み込める。": "It is designed as teaching material for secondary and first-year university students, so the assembly itself can form part of an inquiry project. ",
"物理定数（気圧効果 −0.15 %/hPa、気温効果 −0.09 %/K、遮断能、フォーブッシュ減少の振幅と回復時間）は宇宙線物理の一般的な値を用い、": "The physical constants — barometric effect −0.15 %/hPa, temperature effect −0.09 %/K, cutoff rigidity, and the amplitude and recovery time of a Forbush decrease — are standard values from cosmic-ray physics, ",
"計数のばらつきはポアソン統計で与えている。表示している計数はデモ用の模擬データであり、実観測ではない。": "and the scatter follows Poisson statistics. The counts shown are simulated for this demo, not real observations.",
"1/1.3\" 50 MP CMOS（画素 1.2 µm／2×2 ビニングで 2.4 µm・約 12 MP）": "1/1.3\" 50 MP CMOS (1.2 µm pixels; 2.4 µm and about 12 MP with 2×2 binning)",
