"全天カメラは視野 95° で空全体を見張り、ガンダム望遠鏡は視野 0.42° で一点を深く見る。その間を埋めるのが Draco である。": "The all-sky camera watches the whole sky at 95°, and the Gundam Telescope looks deep at one point across 0.42°. Draco fills the gap between them. ",
"望遠で約 1.7°、広角で 85.7° という二つの視野を同時に持ち、極軸合わせも別のガイド鏡も要らずに 300 秒露出まで追尾できる。": "It holds two fields at once — about 1.7° telephoto and 85.7° wide — and tracks up to 300-second exposures without polar alignment or a separate guide scope. ",
