"札幌から宮崎まで同じ設計で置ける": "One design serves everywhere from Sapporo to Miyazaki",
"ハウジングは全 14 局へ展開することを見越して設計する。まず船橋局（ハブ局）と郡山局（東北拠点）で": "The housing is designed with deployment to all 14 stations in mind. It will first run for a year at Funabashi (the hub) and Koriyama (the Tohoku hub), ",
"1 年間運用し、結露・積雪・風の条件を実測してから横展開する。筐体設計は生産工学部が担当する。": "measuring the real conditions for condensation, snow and wind before wider rollout. The enclosure is designed by the College of Industrial Technology.",
"この望遠鏡の使いみち": "What this telescope is for",
"全天カメラ（95°）→ Draco（1.7°）→ ガンダム望遠鏡（0.42°）の三段構え": "Three tiers: all-sky camera (95°) → Draco (1.7°) → Gundam Telescope (0.42°)",
"使うカメラ": "Camera used",
"流星群の輻射点監視": "Monitoring a shower radiant",
"極大夜に輻射点周辺を高感度で撮り続け、全天カメラでは暗すぎる流星まで数える": "Imaging around the radiant through the night of maximum, counting meteors too faint for the all-sky cameras",
"広角": "Wide",
"流星痕（永続痕）の追跡": "Following a persistent meteor train",
"明るい火球のあとに残る発光雲を数分間追い、高層風の情報を得る": "Tracking the glowing cloud left by a bright fireball for several minutes, which yields upper-level winds",
"望遠": "Telephoto",
"人工衛星・デブリの追尾": "Tracking satellites and debris",
"再突入予報天体を通過に合わせて自動追尾し、光度変化から自転周期を出す": "Automatically following a forecast re-entry object through its pass, and deriving its rotation period from the brightness variation",
"突発天体のフォローアップ": "Transient follow-up",
"新星・超新星・GRB 可視残光の速報を受けて、数十秒で指向し測光する": "On an alert for a nova, supernova or GRB optical afterglow, pointing and measuring within tens of seconds",
"彗星の監視": "Comet monitoring",
"コマの広がりと明るさを継続的に測る": "Measuring the size of the coma and its brightness over time",
"夜空の明るさの検証": "Checking night-sky brightness",
"広角画像の背景輝度を夜空輝度計（SQM）と突き合わせる": "Comparing the background level in the wide-angle image with the sky quality meter",
"付属校のリモート観測": "Remote observing by the affiliated schools",
"校舎から遠隔で指向・露出を操作し、自分の観測として記録を残す": "Students point and expose remotely from their own school and keep the result as their own observation",
"両方": "Both",
"設置する 2 局": "The two stations",
"性格の違う 2 局で 1 年運用し、条件を実測してから横展開する": "A year of operation at two stations of different character, measuring real conditions before wider rollout",
"この局に置く理由": "Why this station",
"ハブ局。ガンダム望遠鏡（400 / 200 mm）と同じ屋上に置き、視野の広さで役割を分ける。分光・SWIR も揃うため、一つの事象を複数の装置で同時に押さえられる": "The hub station. On the same roof as the Gundam Telescope (400 / 200 mm), the two divide the work by field of view. With spectroscopy and SWIR also present, one event can be caught by several instruments at once.",
"東北拠点。船橋より空が暗く、冬季の積雪と低温でハウジングを試験できる。工学部（建築・機械）が筐体の実測を担当する": "The Tohoku hub. Darker skies than Funabashi, and winter snow and cold to test the housing against. The College of Engineering (Architecture and Mechanical) takes the enclosure measurements.",
"装置：DWARFLAB Draco（口径 90 mm・焦点距離 340 mm F3.8、1/1.3\" 50 MP ＋ 広角 1/1.55\"、": "Instrument: DWARFLAB Draco (90 mm aperture, 340 mm focal length at F3.8; 1/1.3\" 50 MP plus 1/1.55\" wide-angle; ",
"露出 1/10000–300 秒、内蔵ガイド、USB 3.0 / Ethernet / NFC、10,000 mAh、本体 5.5 kg）。": "1/10000–300 s exposures; built-in guiding; USB 3.0 / Ethernet / NFC; 10,000 mAh; 5.5 kg body). ",
"諸元は <a href=\"https://www.dwarflab.com/us/products/draco-smart-telescope\" target=\"_blank\" rel=\"noopener\">DWARFLAB 公式</a> による。": "Specifications from <a href=\"https://www.dwarflab.com/us/products/draco-smart-telescope\" target=\"_blank\" rel=\"noopener\">DWARFLAB</a>. ",
"ハウジングは本観測網のための特注品で、仕様は検討中の案である。表示している観測条件はデモ用の模擬データである。": "The housing is a custom build for this network and its specification is still a proposal. The observing conditions shown are simulated for this demo.",
"宇宙線計測器（全 14 局）": "Cosmic-ray detectors (all 14 stations)",
"Accel Kitchen 素粒子検出器組み立てキット。プラスチックシンチレータ 5×5×1 cm ＋ SiPM ＋ ESP32。1 分ごとの計数を常時記録": "Accel Kitchen particle detector kit: 5×5×1 cm plastic scintillator, SiPM and ESP32, recording counts every minute",
"海面での計数は毎分 30 前後で、気圧が 1 hPa 上がるとおよそ 0.15 % 下がる（気圧効果）。": "At sea level the count is about 30 a minute, and it falls roughly 0.15 % for every 1 hPa the pressure rises — the barometric effect. ",
"この観測網は同じ局に気圧計を持っているので、計数をその場で気圧補正でき、残った変動を太陽活動や雷雲の寄与として読める。": "Because this network has a barometer at the same station, the count can be corrected on the spot and what remains read as the contribution of solar activity or thunderclouds. ",
"1 台では統計が足りない変化も、14 局を足し合わせれば見えてくる。": "Changes too small for one unit to resolve statistically emerge once 14 stations are summed.",
"Draco 望遠鏡": "Draco telescope",
"Accel Kitchen 素粒子検出器組み立てキット · プラスチックシンチレータ 5×5×1 cm ＋ SiPM ＋ ESP32": "Accel Kitchen particle detector kit · 5×5×1 cm plastic scintillator, SiPM, ESP32",
"現在からの分": "Minutes from now",
"計数 cpm": "Counts, cpm",
"期待値": "Expected value",
"計数はポアソン統計に従うため、1 分値は期待値のまわりに ±√N でばらつく。": "Counts follow Poisson statistics, so each one-minute value scatters by ±√N about the expected value. ",
"この装置で読みたいのは 1 分ごとの上下ではなく、長時間平均に残る数 % の変化である。": "What this instrument is for is not the minute-to-minute swing but the few per cent that survives in a long average.",
"計数と補正": "Count and corrections",
" cpm（統計誤差 ± ": " cpm (statistical error ± ",
