"雷雲ガンマ線は検知していない。雨量 4 mm/h 以上かつ雲量 85 % 超のときに監視状態へ入る。": "No thunderstorm gamma rays detected. Monitoring begins when rainfall exceeds 4 mm/h and cloud cover exceeds 85 %.",
"宇宙線計測器：Accel Kitchen「素粒子検出器組み立てキット」（プラスチックシンチレータ 5×5×1 cm ＋ SiPM ＋ ESP32）を全 14 局に設置。気圧効果 −0.15 %/hPa・気温効果 −0.09 %/K・地磁気の遮断能・フォーブッシュ減少は宇宙線物理の一般的な値": "Cosmic-ray detectors: the Accel Kitchen “particle detector assembly kit” (5×5×1 cm plastic scintillator, SiPM, ESP32) installed at all 14 stations. The barometric effect (−0.15 %/hPa), temperature effect (−0.09 %/K), cutoff rigidity and Forbush decrease are standard values from cosmic-ray physics.",
"Draco スマート望遠鏡（DWARFLAB、口径 90 mm・焦点距離 340 mm F3.8、1/1.3\" 50 MP ＋ 広角 1/1.55\"、露出 1/10000–300 秒、内蔵ガイド）を船橋局・郡山局に特注ハウジングとともに設置。諸元は DWARFLAB 公式による": "The Draco smart telescope (DWARFLAB: 90 mm aperture, 340 mm focal length at F3.8, 1/1.3\" 50 MP plus 1/1.55\" wide-angle, 1/10000–300 s exposures, built-in guiding), installed with a custom housing at Funabashi and Koriyama. Specifications from DWARFLAB.",
"宇宙線の計数と Draco・特注ハウジングの観測条件（物理の関係式は実際のものだが、表示している値は模擬）": "The cosmic-ray counts, and the observing conditions for Draco and its custom housing (the physical relations are real; the displayed values are simulated)",
