"赤の実線が黄道面より上、破線が下。紫の破線は軌道面と黄道面が交わる<b>交点線</b>で、": "The solid red curve lies above the ecliptic and the dashed part below. The purple dashed line is the <b>line of nodes</b>, where the orbital plane cuts the ecliptic; ",
