" JST のものを描いている。": " JST.",
"軌道要素は多点三角測量で求めた対地速度・輻射点から、地球の公転速度を差し引いて日心軌道に直したもの。": "The orbital elements come from the ground-relative velocity and radiant obtained by multi-station triangulation, with Earth’s orbital motion removed to give the heliocentric orbit. ",
"惑星の位置は JPL「Keplerian Elements for Approximate Positions of the Major Planets」による近似計算で、": "Planet positions are computed from JPL’s “Keplerian Elements for Approximate Positions of the Major Planets”, ",
