"この手順は、光学観測だけで軌道要素の一部を独立に決められることを示している。": "This procedure shows that some orbital elements can be determined independently from optical observation alone. ",
"公開カタログに載っていない物体でも、方位と緯度から軌道傾斜角が、周回ごとの西へのずれから周期が出るので、": "Even for an object absent from the public catalogue, the heading and latitude give the inclination and the westward shift per orbit gives the period, ",
"「カタログのどれでもない」という結論自体を根拠つきで出せる。結果は JAXA 宇宙状況把握（SSA）へ共有する。": "so the conclusion “none of the catalogued objects” can itself be stated with evidence. The results are shared with JAXA Space Situational Awareness (SSA).",
"海岸線は Natural Earth 110m（public domain）。軌道は円軌道近似で、": "Coastlines from Natural Earth 110m (public domain). The orbit is treated as circular, ",
"球面三角法（cos i = sin β cos φ）と地球の自転（15.04°/時）から地上軌跡を求めている。": "and the ground track follows from spherical trigonometry (cos i = sin β cos φ) together with Earth’s rotation at 15.04°/hour. ",
"候補カタログはデモ用の仮想の物体で、実在の衛星ではない。": "The candidate catalogue consists of fictitious objects made for this demo, not real satellites.",
"自然天体（コンドライト的組成）· 連続光は約 ": "Natural body (chondritic composition) · continuum about ",
