"背景の連続光は、衝撃加熱された空気とアブレーション・プラズマの熱放射である。": "The background continuum is thermal emission from shock-heated air and the ablation plasma. ",
"ここでは約 <b>": "Here it is given by Planck’s law as an <b>",
" K の黒体</b>としてプランクの式から与えており、": " K blackbody</b>, ",
"ウィーンの変位則どおり <b>580 nm 付近</b>でなだらかな極大をとる。輝線はこの弱い連続光の上に乗る。": "peaking gently near <b>580 nm</b> as Wien’s displacement law requires. The emission lines sit on top of this weak continuum.",
"自然天体の発光スペクトルの連続光：約 5,000 K の黒体放射（プランクの式）。ウィーンの変位則により 580 nm 付近で極大となる": "The continuum in the natural-body emission spectrum: blackbody radiation at about 5,000 K from Planck’s law, peaking near 580 nm as Wien’s displacement law requires",
