"船橋局のガンダム望遠鏡（口径 400 / 200 mm）と、船橋局・郡山局（工学部）の 2 局に置いた Draco スマート望遠鏡（口径 90 mm・特注ハウジング）を": "The Gundam Telescope at Funabashi (400 / 200 mm) and the Draco smart telescopes (90 mm, in custom housings) at two stations — Funabashi and Koriyama (College of Engineering) — are ",
"遠隔から操作する。観測網が拾った事象へ数十秒で望遠鏡を向けられることが、この画面のねらいである。": "operated remotely. The point of this page is that a telescope can be pointed at anything the network picks up within tens of seconds. ",
