"全天カメラは視野 95° で空全体を見張り、ガンダム望遠鏡は主鏡 600 mm の視野 0.29° で一点を深く見る。その間を埋めるのが Draco である。": "The all-sky camera watches the whole sky at 95°, and the Gundam Telescope’s 600 mm primary looks deep at one point across 0.29°. Draco fills the gap between them. ",
"全天カメラ（95°）→ Draco（1.7°）→ ガンダム望遠鏡 副鏡（1.08°）→ 主鏡（0.29°）と視野を絞っていく": "The field narrows step by step: all-sky camera (95°) → Draco (1.7°) → Gundam secondary (1.08°) → primary (0.29°)",
"ガンダム望遠鏡（口径 600 mm F3.8 ／ 200 mm F3.0・船橋局）の諸元。視野は ZWO ASI174MM の公称画素 5.86 µm 角・1936 × 1216（実寸 11.34 × 7.13 mm）と焦点距離（2,280 / 600 mm）から 2·atan(寸法/2f) で算出し、主鏡 0.285° × 0.179°・副鏡 1.083° × 0.680° となる（同じ計算は遊星人 2024 表 1 の副鏡 1.08° × 0.68° を再現する）。2018 年ふたご座流星群の月面衝突閃光 11 個の観測結果は、阿部新助・柳澤正久・小野寺圭祐「ふたご座流星群の月面衝突閃光から探る活動小惑星 Phaethon の cm サイズ粒子」日本惑星科学会誌 遊星人 33 (3), 262–269 (2024)": "Specifications of the Gundam Telescope (600 mm F3.8 / 200 mm F3.0, Funabashi). The fields of view are computed from the ZWO ASI174MM’s nominal 5.86 µm square pixels, 1936 × 1216 (11.34 × 7.13 mm), and the focal lengths (2,280 / 600 mm) as 2·atan(size/2f), giving 0.285° × 0.179° for the primary and 1.083° × 0.680° for the secondary — the same calculation reproduces the 1.08° × 0.68° given for the secondary in Table 1 of Yuseijin (2024). The results for the 11 lunar impact flashes of the 2018 Geminids come from Shinsuke Abe, Masahisa Yanagisawa and Keisuke Onodera, “Centimetre-sized particles of the active asteroid Phaethon probed by lunar impact flashes of the Geminid meteor shower”, Yuseijin 33 (3), 262–269 (2024).",
"焦点距離 1,520 / 600 mm。2 筒を 1 台の赤道儀に同架": "Focal lengths 1,520 / 600 mm; two tubes on one equatorial mount",
"Abe et al.「遊星人」(2024) 表 1 の構成。視野と画素分解能は ZWO ASI174MM のセンサー実寸と焦点距離から算出した": "The configuration of Table 1 in Abe et al., Yuseijin (2024). Field of view and pixel scale are computed from the physical sensor size of the ZWO ASI174MM and the focal length.",
"光学系の諸元は下記論文 表 1 のとおりで、視野と画素分解能は ": "The optical specifications are those of Table 1 in the paper cited below; the field of view and pixel scale are computed from ",
"ZWO ASI174MM の画素 5.86 µm 角・1936 × 1216（実寸 11.34 × 7.13 mm）と焦点距離（1,520 / 600 mm）から 2·atan(寸法 / 2f) で求めた。": "the ZWO ASI174MM’s 5.86 µm square pixels, 1936 × 1216 (11.34 × 7.13 mm), and the focal lengths (1,520 / 600 mm) as 2·atan(size / 2f). ",
"この計算は、同論文 表 1 の 0.42° × 0.27°・0.8 ″/px（主鏡）と 1.08° × 0.68°・2.0 ″/px（副鏡）を再現する。<br>": "This reproduces the values given in that table: 0.42° × 0.27° and 0.8 ″/px for the primary, 1.08° × 0.68° and 2.0 ″/px for the secondary.<br>",
"0.428° × 0.269°（25.7′ × 16.1′）": "0.428° × 0.269° (25.7′ × 16.1′)",
"全天カメラは視野 95° で空全体を見張り、ガンダム望遠鏡は主鏡 400 mm の視野 0.43° で一点を深く見る。その間を埋めるのが Draco である。": "The all-sky camera watches the whole sky at 95°, and the Gundam Telescope’s 400 mm primary looks deep at one point across 0.43°. Draco fills the gap between them. ",
"全天カメラ（95°）→ Draco（1.7°）→ ガンダム望遠鏡 副鏡（1.08°）→ 主鏡（0.43°）と視野を絞っていく": "The field narrows step by step: all-sky camera (95°) → Draco (1.7°) → Gundam secondary (1.08°) → primary (0.43°)",
"ガンダム望遠鏡（口径 400 mm F3.8 ／ 200 mm F3.0・船橋局）の諸元。視野は ZWO ASI174MM の公称画素 5.86 µm 角・1936 × 1216（実寸 11.34 × 7.13 mm）と焦点距離（1,520 / 600 mm）から 2·atan(寸法/2f) で算出し、主鏡 0.428° × 0.269°・副鏡 1.083° × 0.680° となる（遊星人 2024 表 1 の 0.42° × 0.27°・1.08° × 0.68° を再現する）。2018 年ふたご座流星群の月面衝突閃光 11 個の観測結果は、阿部新助・柳澤正久・小野寺圭祐「ふたご座流星群の月面衝突閃光から探る活動小惑星 Phaethon の cm サイズ粒子」日本惑星科学会誌 遊星人 33 (3), 262–269 (2024)": "Specifications of the Gundam Telescope (400 mm F3.8 / 200 mm F3.0, Funabashi). The fields of view are computed from the ZWO ASI174MM’s nominal 5.86 µm square pixels, 1936 × 1216 (11.34 × 7.13 mm), and the focal lengths (1,520 / 600 mm) as 2·atan(size/2f), giving 0.428° × 0.269° for the primary and 1.083° × 0.680° for the secondary — reproducing the 0.42° × 0.27° and 1.08° × 0.68° of Table 1 in Yuseijin (2024). The results for the 11 lunar impact flashes of the 2018 Geminids come from Shinsuke Abe, Masahisa Yanagisawa and Keisuke Onodera, “Centimetre-sized particles of the active asteroid Phaethon probed by lunar impact flashes of the Geminid meteor shower”, Yuseijin 33 (3), 262–269 (2024).",
