"経年データを国の施策に載せる。既存事業に合わせた形で出し、足りない部分を補う": "Feeding the long-term record into national policy: delivered in the form the existing programme uses, and filling in what it lacks",
"提案": "Proposal",
"環境省は星空公団と共同で、": "Together with Hoshizora Kodan, the Ministry of the Environment has run a ",
"平成 30 年度から夏（8 月）と冬（1 月）の新月前後 2 週間": "“star-watching” survey since FY2018, over the two weeks around new moon in summer (August) and winter (January)",
"に「星空観察」を実施している。デジタル一眼で天頂を撮った RAW 画像から夜空の明るさ（mag/arcsec²）を求めるもので、": ". Night sky brightness (mag/arcsec²) is derived from RAW images of the zenith taken with a digital SLR, ",
"結果は国立環境研究所「環境展望台」の環境 GIS に": "and the results are published as a map layer, ",
"「星空観察結果」": "“Star-watching results”",
"として地図公開されている。本観測網は": "in the environmental GIS of NIES’s “Environmental Observatory”. This network measures ",
"同じ量（天頂の mag/arcsec²）を 14 局で通年・連続に測る": "the same quantity — zenith mag/arcsec² — continuously all year at 14 stations",
"ので、年 2 回・1 晩の点観測を時間方向に埋め、経年変化の検出力を上げられる。": ", so it fills in the time between the twice-yearly single-night measurements and sharpens the detection of long-term change.",
